/* R5-B 有限复核：只接已经落地、已经影响玩家的决定 —— 目前只有 R5-C 的违约扣押。
 * 证据、时限、一次复核、有限结果四件事都要能复查；
 * 复核永远不清掉欠款本身，也永远不会凭空发一笔钱。
 * ============================================================ */
var REVIEW_WINDOW = 7;        /* 扣押后 7 天内可申请 */
var REVIEW_DELAY = 3;         /* 受理后第 3 天出结果 */
var REVIEW_RELIEF_CAP = 20;   /* 罚息减免封顶 20 金 */
function normalizeCreditReview(raw) {
  if (!raw || typeof raw !== 'object') return null;
  if (!isInt(raw.day) && !isInt(raw.seizeDay)) return null;
  var day = isInt(raw.day) ? clamp(raw.day, 0, 1000000) : 0;
  return {
    tx: typeof raw.tx === 'string' ? raw.tx.slice(0, 48) : '',
    day: day,
    seizeDay: isInt(raw.seizeDay) ? clamp(raw.seizeDay, 0, 1000000) : day,
    dueDay: isInt(raw.dueDay) ? clamp(raw.dueDay, 0, 1000000) : day,
    value: isInt(raw.value) ? Math.max(0, raw.value) : 0,
    debtAt: isInt(raw.debtAt) ? Math.max(0, raw.debtAt) : 0,
    status: ['filed', 'granted', 'upheld'].indexOf(raw.status) >= 0 ? raw.status : 'filed',
    decidedDay: isInt(raw.decidedDay) ? clamp(raw.decidedDay, 0, 1000000) : 0,
    relief: Math.min(REVIEW_RELIEF_CAP, Math.max(0, isInt(raw.relief) ? raw.relief : 0)),
    reason: typeof raw.reason === 'string' ? raw.reason.slice(0, 80) : ''
  };
}
/* 还有没有可复核的扣押：必须在时限内、这份扣押还没复核过 */
function creditReviewTarget() {
  var c = creditTick();
  if (c.status !== 'default' || !c.seized.length) return null;
  var s = c.seized[c.seized.length - 1];
  if (c.review && c.review.seizeDay === s.day) return null;
  if (state.totalDay - s.day > REVIEW_WINDOW) return null;
  return s;
}
function creditFileReview() {
  var c = creditTick();
  var s = creditReviewTarget();
  if (!s) return false;
  c.review = {
    tx: 'review:seize:d' + state.totalDay + ':#' + (c.tx.length + 1),
    day: state.totalDay, seizeDay: s.day, dueDay: state.totalDay + REVIEW_DELAY,
    value: (ITEMS[s.id] ? (ITEMS[s.id].sell || 0) : 0) * s.qty,
    debtAt: isInt(s.debtAt) ? s.debtAt : creditDebt(c), status: 'filed', decidedDay: 0, relief: 0, reason: ''
  };
  creditTx('review', 0, '申请复核第 ' + s.day + ' 天的违约扣押');
  toast('复核已受理，第 ' + c.review.dueDay + ' 天出结果。');
  markDirty();
  return true;
}
/* 裁定只有一个客观标准：扣押当日取走的东西是不是超过了当时的欠款。
   超出的部分退还、罚息减免封顶 ' + REVIEW_RELIEF_CAP + ' 金；没超出就维持原判，理由写清当时那两笔数。 */
function creditResolveReview() {
  var c = creditState();
  var rv = c.review;
  if (!rv || rv.status !== 'filed' || state.totalDay < rv.dueDay) return null;
  if (rv.value > rv.debtAt) {
    rv.status = 'granted'; rv.relief = Math.min(REVIEW_RELIEF_CAP, c.lateFee);
    c.lateFee = Math.max(0, c.lateFee - rv.relief);
    var back = c.seized.filter(function (s) { return s.day === rv.seizeDay; });
    if (back.length) {
      invAdd(back[0].id, back[0].qty);
      c.seized = c.seized.filter(function (x) { return x.day !== rv.seizeDay; });
      rv.reason = '扣押当日取走 ' + rv.value + ' 金，超过当时欠款 ' + rv.debtAt + ' 金：多扣部分原物归还，罚息减免 ' + rv.relief + ' 金，欠款本金不变。';
    } else {
      rv.reason = '多扣 ' + (rv.value - rv.debtAt) + ' 金，罚息减免 ' + rv.relief + ' 金，欠款本金不变。';
    }
  } else {
    rv.status = 'upheld'; rv.relief = 0;
    rv.reason = '扣押当日取走 ' + rv.value + ' 金，未超过当时欠款 ' + rv.debtAt + ' 金：维持原判，罚息不变。';
  }
  rv.decidedDay = state.totalDay;
  creditTx('review_result', 0, rv.status === 'granted' ? '复核成立' : '复核不成立');
  markDirty();
  return rv;
}
/* 复核只在银行面板里存在一个入口：先结算已有结果，再决定要不要给新申请 */
function creditReviewPanel(b) {
  var c = creditState();
  creditResolveReview();
  var rv = c.review, s = rv ? null : creditReviewTarget();
  if (!rv && !s) return;
  var box = el('div', 'panel-box');
  box.appendChild(el('div', 'section-title', '违约处置 · 复核'));
  if (!rv) {
    box.appendChild(el('p', 'muted', '你对第 ' + s.day + ' 天的扣押有异议，可以在 ' + REVIEW_WINDOW +
      ' 天内申请一次复核。复核只看一件事：扣押当日取走的东西是不是超过了当时的欠款。'));
    box.appendChild(el('p', 'req-chip', '证据：第 ' + s.day + ' 天扣押 ' + itemName(s.id) + ' ×' + s.qty +
      '，当时欠款 ' + (isInt(s.debtAt) ? s.debtAt : creditDebt(c)) + ' 金。'));
    box.appendChild(mkBtn('申请复核 · 30分钟', '', function () { creditFileReview(); refreshWindow(); }));
    b.appendChild(box);
    return;
  }
  box.appendChild(el('p', 'req-chip' + (rv.status === 'granted' ? ' ok' : ''),
    rv.status === 'filed' ? '复核已受理' : rv.status === 'granted' ? '复核成立' : '复核不成立'));
  box.appendChild(el('p', 'muted', '申请日第 ' + rv.day + ' 天，扣押日第 ' + rv.seizeDay + ' 天，结果应在第 ' + rv.dueDay + ' 天给出。'));
  box.appendChild(el('p', null, '证据：扣押当日取走 ' + rv.value + ' 金，当时欠款 ' + rv.debtAt + ' 金。'));
  if (rv.status === 'filed') box.appendChild(el('p', 'muted', '还没到出结果的日子；每份扣押只能复核一次。'));
  else {
    box.appendChild(el('p', null, '第 ' + rv.decidedDay + ' 天裁定：' + rv.reason));
    box.appendChild(el('p', 'muted', '复核最多减免 ' + REVIEW_RELIEF_CAP + ' 金罚息，不清欠款本金，也不发钱。'));
  }
  b.appendChild(box);
}

/* R5-C 有限信用合同：一份市立小额周转贷。
 * 只做本金、期限、利息、偿还、逾期和一次协商，不做宏观市场，也不铺第二张合同。
 * 放款不是收入：它只是把将来要还的钱提前放到账上，日结算的收入账不会记它。
 * 合同的钱只往一个方向走 —— 放款 +N，还款 −M，且 M ≥ N，差额就是利息。
 * ============================================================ */
var CREDIT_PRINCIPAL = 300;
var CREDIT_RATE = 0.15;
var CREDIT_DAYS = 14;
var CREDIT_LATE_PER_DAY = 2;
var CREDIT_LATE_CAP = 40;
var CREDIT_DEFAULT_DAYS = 7;
var CREDIT_RENEGOTIATE_RATE = 0.21;
var CREDIT_RENEGOTIATE_DAYS = 7;
/* 只有这些能抵债：原料与石料，不动票据、作物与设备，免得一次违约把家底抄空 */
var CREDIT_SEIZABLE = ['gem', 'stone_block', 'iron_ingot', 'copper_ingot', 'limestone', 'hardwood', 'plank', 'timber'];
function newCredit() {
  return { status: 'none', principal: 0, rate: CREDIT_RATE, startDay: 0, dueDay: 0, dueTotal: 0,
    paid: 0, lateDays: 0, lateFee: 0, lastCheckDay: 0, renegotiated: false, seizedOnce: false, seized: [], review: null, tx: [] };
}
function normalizeCredit(raw) {
  var c = newCredit();
  if (!raw || typeof raw !== 'object') return c;
  c.status = ['none', 'active', 'default'].indexOf(raw.status) >= 0 ? raw.status : 'none';
  c.principal = Math.min(1000000, Math.max(0, isInt(raw.principal) ? raw.principal : 0));
  /* 利率只接受 0—50% 之间的实数，超界就退回标准利率，不把坏档当成超高息合同 */
  c.rate = (isFinite(raw.rate) && raw.rate > 0 && raw.rate <= 0.5) ? raw.rate : CREDIT_RATE;
  ['startDay', 'dueDay', 'lastCheckDay'].forEach(function (k) { c[k] = isInt(raw[k]) ? clamp(raw[k], 0, 1000000) : 0; });
  c.dueTotal = isInt(raw.dueTotal) ? Math.max(0, raw.dueTotal) : 0;
  c.paid = Math.min(1000000, Math.max(0, isInt(raw.paid) ? raw.paid : 0));
  c.lateDays = Math.min(100000, Math.max(0, isInt(raw.lateDays) ? raw.lateDays : 0));
  c.lateFee = Math.min(CREDIT_LATE_CAP, Math.max(0, isInt(raw.lateFee) ? raw.lateFee : 0));
  /* 只认真布尔：坏档里的 "yes"/1 不算已协商过，否则会被字符串永久锁死协商 */
  c.renegotiated = raw.renegotiated === true;
  c.seized = Array.isArray(raw.seized) ? raw.seized.filter(function (s) {
    return s && ITEMS[s.id] && isInt(s.qty) && s.qty > 0;
  }).slice(0, 12).map(function (s) {
    var entry = { id: s.id, qty: Math.min(999, s.qty), day: isInt(s.day) ? clamp(s.day, 0, 1000000) : 0 };
    if (isInt(s.debtAt) && s.debtAt >= 0) entry.debtAt = s.debtAt;
    return entry;
  }) : [];
  /* R5-B：复核只对已落地的那次扣押有效，缺字段或整条坏掉都退回「没有复核」 */
  c.review = normalizeCreditReview(raw.review);
  c.seizedOnce = raw.seizedOnce === true || c.seized.length > 0 || !!c.review;
  c.tx = Array.isArray(raw.tx) ? raw.tx.filter(function (t) { return t && typeof t === 'object' && isInt(t.amt); })
    .slice(-40).map(function (t) {
      return { tx: String(t.tx || '').slice(0, 48), kind: String(t.kind || '').slice(0, 16), amt: t.amt, day: isInt(t.day) ? clamp(t.day, 0, 1000000) : 0, note: String(t.note || '').slice(0, 60) };
    }) : [];
  /* 自洽：没放款的档不该留着还款日与罚息；欠款不得低于本金 */
  if (c.status === 'none') { c.dueDay = 0; c.dueTotal = 0; c.lateDays = 0; c.lateFee = 0; c.paid = 0; c.renegotiated = false; c.seized = []; c.review = null; }
  if (c.dueTotal < c.principal) c.dueTotal = c.principal;
  return c;
}
function creditState() { var e = exploreState(); if (!e.credit || typeof e.credit !== 'object') e.credit = newCredit(); return e.credit; }
function creditTx(kind, amt, note) {
  var c = creditState();
  c.tx.push({ tx: 'credit:' + kind + ':d' + state.totalDay + ':#' + (c.tx.length + 1), kind: kind, amt: amt, day: state.totalDay, note: note || '' });
  if (c.tx.length > 40) c.tx.splice(0, c.tx.length - 40);
}
/* 当前欠款 = 本金 + 利息 + 罚息 − 已还；永远不小于本金，不允许凭空归零 */
function creditDebt(c) {
  c = c || creditState();
  return Math.max(c.principal, c.dueTotal + c.lateFee - c.paid);
}
/* 逾期天数由日期派生，不靠计时器；同一天重复调用不会重复计罚息 */
function creditTick() {
  var c = creditState();
  if (c.status === 'none' || !c.dueDay) return c;
  if (state.totalDay > c.lastCheckDay) {
    c.lateDays = Math.max(0, state.totalDay - c.dueDay);
    var relief = c.review && c.review.status === 'granted' ? c.review.relief : 0;
    c.lateFee = Math.max(0, Math.min(CREDIT_LATE_CAP, c.lateDays * CREDIT_LATE_PER_DAY) - relief);
    if (c.lateDays >= CREDIT_DEFAULT_DAYS && c.status === 'active') c.status = 'default';
    c.lastCheckDay = state.totalDay;
  }
  /* 违约扣押一次就够：按欠款从可抵债清单里取最贵的一件，不清空玩家整包。
     已经扣过就不再扣 —— 反复开银行不能变成连续抄家。 */
  if (c.status === 'default' && c.lateDays >= CREDIT_DEFAULT_DAYS && !c.seizedOnce && !c.seized.length) creditSeizeOnce();
  return c;
}
function creditSeizeOnce() {
  var c = creditState();
  if (c.seizedOnce) return false;
  var debt = creditDebt(c);
  for (var i = 0; i < CREDIT_SEIZABLE.length; i++) {
    var id = CREDIT_SEIZABLE[i], n = invCount(id);
    if (!n) continue;
    var value = (ITEMS[id].sell || 0);
    if (value <= 0) continue;
    var take = Math.min(n, Math.max(1, Math.ceil(debt / value)));
    invRemove(id, take);
    c.seized.push({ id: id, qty: take, day: state.totalDay, debtAt: debt });
    c.seizedOnce = true;
    creditTx('seize', -value * take, '违约扣押 ' + itemName(id) + ' ×' + take);
    return true;
  }
  return false;
}
function creditTake() {
  var c = creditState();
  if (c.status !== 'none') return false;
  var due = Math.round(CREDIT_PRINCIPAL * (1 + CREDIT_RATE));
  c.status = 'active';
  c.principal = CREDIT_PRINCIPAL; c.rate = CREDIT_RATE;
  c.startDay = state.totalDay; c.dueDay = state.totalDay + CREDIT_DAYS;
  c.dueTotal = due; c.paid = 0; c.lateDays = 0; c.lateFee = 0;
  c.lastCheckDay = state.totalDay; c.renegotiated = false;
  c.seizedOnce = false; c.seized = []; c.review = null;
  state.coins += CREDIT_PRINCIPAL;
  creditTx('draw', CREDIT_PRINCIPAL, '市立小额周转贷放款');
  toast('放款 ' + CREDIT_PRINCIPAL + ' 金，第 ' + c.dueDay + ' 天前归还 ' + due + ' 金。放款不算收入。');
  markDirty();
  return true;
}
/* 一次性还清：还清就把合同归档，扣押物退还 */
function creditRepay() {
  creditTick();
  var c = creditState();
  if (c.status === 'none') return false;
  var debt = creditDebt(c);
  if (!payExplore({ coins: debt })) return false;
  c.paid += debt;
  state.coins = state.coins;              // payExplore 已扣款，这里只登记账
  creditTx('repay', -debt, '一次性还清本金与利息');
  var back = c.seized.splice(0, c.seized.length);
  back.forEach(function (s) { invAdd(s.id, s.qty); });
  c.status = 'none'; c.principal = 0; c.dueTotal = 0; c.paid = 0; c.lateFee = 0; c.lateDays = 0;
  c.dueDay = 0; c.renegotiated = false; c.lastCheckDay = 0;
  /* 合同结清＝争议一并了结：复核记录不再挂在已归档的合同上，
     裁定结果保留在 credit.tx 流水里，随时可查。 */
  if (c.review) creditTx('review_closed', 0, c.review.status === 'granted' ? '结清前复核成立' : (c.review.status === 'upheld' ? '结清前复核不成立' : '结清前复核未出结果'));
  c.review = null;
  toast('合同结清，' + (back.length ? '扣押物已归还。' : ''));
  markDirty();
  return true;
}
/* 一次协商：展期 7 天，利息上浮到 21%。用过就没有第二次。 */
function creditRenegotiate() {
  creditTick();
  var c = creditState();
  if (c.status === 'none' || c.renegotiated) return false;
  c.renegotiated = true;
  c.rate = CREDIT_RENEGOTIATE_RATE;
  c.dueTotal = Math.round(c.principal * (1 + CREDIT_RENEGOTIATE_RATE));
  c.dueDay = state.totalDay + CREDIT_RENEGOTIATE_DAYS;
  c.lateDays = 0; c.lateFee = 0; c.lastCheckDay = state.totalDay;
  creditTx('renegotiate', 0, '一次协商：展期 ' + CREDIT_RENEGOTIATE_DAYS + ' 天，利息 ' + Math.round(CREDIT_RENEGOTIATE_RATE * 100) + '%');
  toast('谈成一次展期：第 ' + c.dueDay + ' 天前还 ' + c.dueTotal + ' 金。只能谈这一次。');
  markDirty();
  return true;
}
/* ---------- 银行窗口里的合同面板 ---------- */
function creditPanel(b) {
  var c = creditTick();
  var box = el('div', 'panel-box');
  box.appendChild(el('div', 'section-title', '市立小额周转贷'));
  if (c.status === 'none') {
    box.appendChild(el('p', 'muted', '本金 ' + CREDIT_PRINCIPAL + ' 金，期限 ' + CREDIT_DAYS + ' 天，利息 ' +
      Math.round(CREDIT_RATE * 100) + '%，到期一次还清 ' + Math.round(CREDIT_PRINCIPAL * (1 + CREDIT_RATE)) +
      ' 金。逾期每天加 ' + CREDIT_LATE_PER_DAY + ' 金罚息（封顶 ' + CREDIT_LATE_CAP + ' 金），逾期满 ' +
      CREDIT_DEFAULT_DAYS + ' 天按违约处置。放款不是收入，是借来的钱。'));
    box.appendChild(el('p', 'muted', '手上没有别的钱时它能救一个急，但要先想清楚第 ' + CREDIT_DAYS + ' 天拿什么还。'));
    box.appendChild(mkBtn('申请周转贷 · 本金 ' + CREDIT_PRINCIPAL + ' 金 · 30分钟', '', function () {
      creditTake(); refreshWindow();
    }));
    b.appendChild(box);
    return;
  }
  var debt = creditDebt(c);
  box.appendChild(el('p', 'req-chip' + (c.status === 'default' ? '' : ' ok'),
    (c.status === 'default' ? '违约处置中' : '在贷') + ' · 第 ' + c.startDay + ' 天放款 · 第 ' + c.dueDay +
    ' 天到期 · 还欠 ' + debt + ' 金'));
  box.appendChild(el('p', null, '本金 ' + c.principal + ' 金，利息 ' + Math.round(c.rate * 100) + '%，' +
    '到期应付 ' + c.dueTotal + ' 金，已还 ' + c.paid + ' 金，罚息 ' + c.lateFee + ' 金。' +
    (c.lateDays > 0 ? '已逾期 ' + c.lateDays + ' 天。' : '还有 ' + Math.max(0, c.dueDay - state.totalDay) + ' 天到期。')));
  if (c.seized.length) box.appendChild(el('p', 'muted', '违约扣押：' + c.seized.map(function (s) { return itemName(s.id) + ' ×' + s.qty; }).join('、') + '。还清合同后原物归还。'));
  if (c.lateDays > 0) box.appendChild(el('p', 'muted', '罚息按逾期天数累计，封顶 ' + CREDIT_LATE_CAP + ' 金；重复打开面板不会重复计。'));
  if (c.renegotiated) box.appendChild(el('p', 'muted', '已经协商过一次：展期到第 ' + c.dueDay + ' 天，利息上浮到 ' + Math.round(c.rate * 100) + '%。'));
  var row = el('div', 'row');
  row.appendChild(mkBtn('一次性还清 ' + debt + ' 金', '', function () { creditRepay(); refreshWindow(); }));
  if (!c.renegotiated) {
    row.appendChild(mkBtn('申请一次协商 · 展期 ' + CREDIT_RENEGOTIATE_DAYS + ' 天 · 利息上浮 · 30分钟', '', function () {
      creditRenegotiate(); refreshWindow();
    }));
  }
  box.appendChild(row);
  b.appendChild(box);
  if (c.tx.length) box.appendChild(el('p', 'muted', '最近流水：' + c.tx.slice(-4).map(function (t) {
    return '第' + t.day + '天 ' + t.kind + (t.amt ? (t.amt > 0 ? ' +' + t.amt : ' ' + t.amt) : '') + (t.note ? '（' + t.note + '）' : '');
  }).join('；')));
}
/* R5-C 票据单一权威报价表。
 * cost    取得成本的金币当量（含折算的材料），只用来守住不变式
 * coins   实际向玩家收的金币；0 表示靠材料作保，不收现钱
 * face    票面兑付价；term 是兑付期限（天），0 表示随时可兑
 * pledge  典当估值；source 取得来源
 * 守住的不变式：cost ≥ face、cost ≥ pledge、pledge × 1.1 ≥ pledge。
 * 票据是凭证不是金条：任何一张都不许靠倒手凭空生出金币。 */
var BILL_QUOTES = {
  bill:           { cost: 110, coins: 0,   face: 87,  term: 0,  pledge: 0,   source: '金库开票 · 铜锭 2' },
  share_cert:     { cost: 252, coins: 200, face: 160, term: 0,  pledge: 0,   source: '交易所认购 · 200 金 + 面粉 2' },
  warehouse_deed: { cost: 204, coins: 0,   face: 200, term: 0,  pledge: 150, source: '金库立契 · 板材 6' },
  bond:           { cost: 240, coins: 240, face: 250, term: 28, pledge: 160, source: '市政厅认购 · 240 金' }
};
var BILL_IDS = ['bill', 'share_cert', 'warehouse_deed', 'bond'];
/* 典当估值不得超过无条件票面，且赎回要连本带息；这两个数只在这里算一次。 */
function billPledgeValue(id){ var q=BILL_QUOTES[id]; return q&&q.pledge?Math.min(q.pledge,q.face):0; }
function billRedeemDue(id){ var q=BILL_QUOTES[id]; return q?Math.round(q.face)+Math.floor(q.face*0.1):0; }

/* --- 作物表 ---
   seasons：可下种的季节。季节外不播下，已在地里的作物跨季照常生长、
   不会因为换季被清掉或减产——见 toolSeed 的注释与跨季提示。 */
var CROPS = {
  radish:     { id: 'radish',     name: '萝卜', seed: 'seed_radish',     produce: 'radish',     seedPrice: 5,  sell: 9,  growDays: 3, regrow: 0, yield: 3, seasons: ['春', '秋'] },
  potato:     { id: 'potato',     name: '土豆', seed: 'seed_potato',     produce: 'potato',     seedPrice: 12, sell: 20, growDays: 5, regrow: 0, yield: 3, seasons: ['春', '夏'] },
  strawberry: { id: 'strawberry', name: '草莓', seed: 'seed_strawberry', produce: 'strawberry', seedPrice: 25, sell: 15, growDays: 6, regrow: 3, yield: 3, seasons: ['春'] }
};
var CROP_ORDER = ['radish', 'potato', 'strawberry'];

/* --- 土壤肥力与轮作（§32.2）---
   设计约束（照总规原文，不自行放宽）：
   - 肥力按田区记录 0—100，界面只展示「低／适宜／充足」三档 + 实际影响
   - 连续同类种植缓慢下降；轮作与堆肥恢复
   - 低肥力影响产量，不突然杀死作物
   - 首批不做酸碱、十余种元素、虫害概率表
   - 旧作物迁移时处于正常肥力，历史行为不追溯处罚
   肥力挂在 state.plots[key] 上，与 water/age 并列，不改动既有字段语义。 */
var FERT = { MIN: 0, MAX: 100, DEF: 60, LOW: 34, GOOD: 66, COMPOST_BONUS: 8 };   // DEF=旧档默认（正常，不追溯）
/* 轮作组：叶菜／根茎／豆类。组间轮换有利，同组连作缓慢下降。 */
var CROP_GROUPS = {
  leaf:  { id: 'leaf',  name: '叶菜类', members: ['radish', 'strawberry'] },
  root:  { id: 'root',  name: '根茎类', members: ['potato'] },
  legume:{ id: 'legume',name: '豆类',   members: [] }   // 豆类首批暂无作物，占位等后续作物接入
};
var CROP_TO_GROUP = {};   // 播种时建立，不硬编码散落
Object.keys(CROP_GROUPS).forEach(function (g) {
  CROP_GROUPS[g].members.forEach(function (cid) { CROP_TO_GROUP[cid] = g; });
});

function plotFertility(p) {
  if (!p) return FERT.DEF;
  var v = p.fertility;
  if (typeof v !== 'number' || !isFinite(v)) return FERT.DEF;
  return clamp(Math.floor(v), FERT.MIN, FERT.MAX);
}
/* 三档显示：只给低／适宜／充足，不暴露数字（§32.2「界面只展示低／适宜／充足和实际影响」） */
function fertilityTier(v) {
  var f = (typeof v === 'number') ? v : FERT.DEF;
  if (f < FERT.LOW)  return { id: 'low',  label: '低',   hint: '产量受影响，轮作或堆肥可恢复' };
  if (f < FERT.GOOD) return { id: 'good', label: '适宜', hint: '正常生长' };
  return { id: 'high', label: '充足', hint: '肥力充沛' };
}
/* 产量系数：低肥力压产量但绝不死作物（最低 0.5，保底一半） */
function fertilityYieldFactor(v) {
  var f = (typeof v === 'number') ? v : FERT.DEF;
  if (f >= FERT.GOOD) return 1;
  if (f >= FERT.LOW)  return 0.85;
  return 0.5;   // 低肥力：产量减半，不枯死
}
/* 轮作提示：告诉玩家下一季种什么有帮助（§32.2） */
function rotationHint(cropId, lastGroup) {
  if (!CROPS[cropId]) return null;
  var g = CROP_TO_GROUP[cropId];
  if (!g) return null;
  if (!lastGroup) return null;                       // 无历史，不打扰
  if (g !== lastGroup) return { good: true, text: CROP_GROUPS[g].name + '，与上一季不同组，恢复快' };
  // 同组连作：找一个不同的组做建议
  var alt = Object.keys(CROP_GROUPS).filter(function (k) { return k !== g && CROP_GROUPS[k].members.length > 0; });
  if (alt.length) return { good: false, text: '与上一季同组（' + CROP_GROUPS[g].name + '），改种' + CROP_GROUPS[alt[0]].name + '更有帮助' };
  return { good: false, text: '与上一季同组（' + CROP_GROUPS[g].name + '），连作会缓慢消耗肥力' };
}
/* 采集最近一季的轮作组（从相邻田块历史推断；本项目单块记录足够） */
function lastRotationGroup(x, y) {
  var pk = key2(x, y);
  var p = state.plots[pk];
  return p && p.lastGroup ? p.lastGroup : null;
}
/* 每日肥力变化（§32.2「连续同类种植缓慢下降」「轮作、堆肥恢复」）
   刻意的缓坡设计：单季连作只掉 2—3 点，玩家要连种好几季才会感到压力，
   不会因为一次疏忽就毁掉一块地。低肥力只压产量，不会枯死作物。 */
var FERT_RATE = {
  sameGroup: -2,    // 同组连作：缓慢下降
  diffGroup: 1,     // 换组种植：小幅恢复
  fallow: 3         // 空地休耕：恢复更快
};
/* 返回该田块今日肥力变化量（不含堆肥加成）
   注意：lastGroup 在播种时就写成当前组，所以它代表"本季"，
   判断连作要看 prevGroup（播种前那一季的组），不能拿 lastGroup 比。 */
function fertilityDeltaToday(p) {
  if (!p) return 0;
  if (!p.crop) return FERT_RATE.fallow;                 // 休耕恢复
  var g = CROP_TO_GROUP[p.crop];
  if (!g) return 0;
  if (!p.prevGroup) return FERT_RATE.sameGroup;          // 没有上一季记录：按新地首次种植处理
  return (p.prevGroup !== g) ? FERT_RATE.diffGroup : FERT_RATE.sameGroup;
}
/* 应用每日肥力变化，返回实际变化量（供结算摘要报告） */
function applyFertilityDaily(p) {
  if (!p) return 0;
  var d = fertilityDeltaToday(p);
  if (!d) return 0;
  var before = plotFertility(p);
  var after = clamp(before + d, FERT.MIN, FERT.MAX);
  p.fertility = after;
  return after - before;
}

/* 钓鱼鱼池：与 ITEMS 里 kind:'fish' 的物品表保持同一套 id，
   钓到的鱼必须能直接进背包和出货箱，所以两边绝不能各写一份。
   分层按售价/稀有度：T1 常见、T2 少见、T3 稀有（§32.5「有限鱼种…首批不做几十个隐藏钓率」）。 */

/* 合并说明：肥力统一采用远端的「按地块」方案（plotFertility / FERT / CROP_GROUPS）。
   堆肥箱写的就是 p.fertility，两套并存会让堆肥变成写了不生效。
   本地原先的按田区存储改为下面的汇总视图：田区肥力由该区各地块平均得出，
   仍然满足 §32.2「按田区只展示低／适宜／充足三档」。 */
var FARM_ZONES = [
  { id: 'z1', name: '北田区', x0: 6,  y0: 4,  x1: 13, y1: 6 },
  { id: 'z2', name: '东北区', x0: 14, y0: 4,  x1: 21, y1: 6 },
  { id: 'z3', name: '西南区', x0: 6,  y0: 7,  x1: 13, y1: 9 },
  { id: 'z4', name: '东南区', x0: 14, y0: 7,  x1: 21, y1: 9 }
];
function farmZoneAt(x, y) {
  for (var i = 0; i < FARM_ZONES.length; i++) {
    var z = FARM_ZONES[i];
    if (x >= z.x0 && x <= z.x1 && y >= z.y0 && y <= z.y1) return z.id;
  }
  return null;
}
/* 田区汇总：把该区所有已翻地块的肥力平均，仍只对外暴露三档 */
function zoneFertilityAvg(zoneId) {
  var sum = 0, n = 0;
  for (var key in state.plots) {
    if (!Object.prototype.hasOwnProperty.call(state.plots, key)) continue;
    var xy = key.split(',');
    if (farmZoneAt(+xy[0], +xy[1]) !== zoneId) continue;
    sum += plotFertility(state.plots[key]); n++;
  }
  return n ? Math.round(sum / n) : FERT.DEF;
}
function fertilityAt(x, y) {
  var p = state.plots[key2(x, y)];
  return p ? plotFertility(p) : FERT.DEF;
}
function fertilityBand(v) { var t = fertilityTier(v); return {id:t.id,name:t.label,effect:t.hint}; }
/* 产量增减：交给远端的乘法系数统一处理，这里只保留旧接口避免调用点报错 */
function fertilityYieldBonus() { return 0; }
function fertilityState() {
  var zones = {};
  FARM_ZONES.forEach(function(z) { zones[z.id] = zoneFertilityAvg(z.id); });
  return { zones: zones, compost: 0 };
}
