function storyEntryForScene(sceneId) {
  for (var i = 0; i < STORY_ENTRIES.length; i++) if (STORY_ENTRIES[i].storyScene === sceneId) return STORY_ENTRIES[i];
  return null;
}

/* 一个站位是不是「工具目标附近」：
   玩家站在这样的格子上时，最可能去点的是旁边那件工具（锄地、砍树、采石）。
   入口的 stand 里如果含这种格子，点工具就会被入口抢走，锄地和采集都做不成。 */
function storyToolTargetNear(sceneId, x, y) {
  var map = MAPS[sceneId];
  if (!map) return false;
  var pa = map.plantArea;
  var inPlot = function (px, py) { return !!pa && px >= pa.x0 && px <= pa.x1 && py >= pa.y0 && py <= pa.y1; };
  if (inPlot(x, y)) return true;
  if (inPlot(x - 1, y) || inPlot(x + 1, y) || inPlot(x, y - 1) || inPlot(x, y + 1)) return true;
  var nodes = EXPLORE_NODES[sceneId] || {};
  if (nodes[x + ',' + y]) return true;
  var list = (map.trees || []).concat(map.rocks || []).concat(map.berries || []);
  for (var i = 0; i < list.length; i++) {
    var p = list[i];
    if (Math.abs(p[0] - x) + Math.abs(p[1] - y) <= 1) return true;
  }
  return false;
}

/* 把入口登记成既有场景里的真实交互点。
   stand 用「入口格四周真正可走的格子」算出来，不写死坐标：
   家具、桥状态和资源节点都会改通行，写死的 stand 迟早会失效。
   紧挨工具目标格的站位一律不算——那会把锄地和采集抢走。
   每次换场景重算一次，登记本身不重复添加。 */
function registerStoryEntries() {
  STORY_ENTRIES.forEach(function (def) {
    if (!MAPS[def.scene]) return;
    var list = INTERACTABLES[def.scene] = INTERACTABLES[def.scene] || [];
    var it = null, i;
    for (i = 0; i < list.length; i++) if (list[i].id === def.id) { it = list[i]; break; }
    if (!it) {
      it = { id: def.id, x: def.x, y: def.y, kind: 'storyEntry', label: def.label, story: def };
      list.push(it);
    }
    var stand = [];
    [[def.x, def.y - 1], [def.x + 1, def.y], [def.x, def.y + 1], [def.x - 1, def.y]].forEach(function (c) {
      if (isSolid(def.scene, c[0], c[1])) return;
      if (storyToolTargetNear(def.scene, c[0], c[1])) return;
      stand.push(c);
    });
    if (!isSolid(def.scene, def.x, def.y) && !storyToolTargetNear(def.scene, def.x, def.y)) stand.unshift([def.x, def.y]);
    it.stand = stand;
  });
}

/* ============================================================
   剧情状态与引擎
   ============================================================ */
function newStoryState() {
  return {
    started: false,
    act: 0,
    tasks: {},
    scenes: {},
    evidence: {},
    choices: {},
    flags: {},
    lenaStance: '',
    routeMethod: '',
    rescueMethod: '',
    evacPriority: '',
    householdChoices: {},
    support: {},
    outcome: ''
  };
}

/* 旧档归一化：缺字段补默认，不凭空造出玩家没做过的事 */
function normalizeStory(raw) {
  var d = newStoryState();
  if (!raw || typeof raw !== 'object') return d;
  d.started = raw.started === true;
  d.act = isInt(raw.act) && raw.act >= 0 ? raw.act : 0;
  if (raw.tasks && typeof raw.tasks === 'object') {
    for (var k in raw.tasks) {
      var v = raw.tasks[k];
      if (v === 'active' || v === 'done' || v === 'available') d.tasks[k] = v;
    }
  }
  if (raw.scenes && typeof raw.scenes === 'object') {
    for (var sk in raw.scenes) {
      var sv = raw.scenes[sk];
      if (!sv || typeof sv !== 'object') continue;
      d.scenes[sk] = {
        seen: sv.seen === true,
        skipped: sv.skipped === true,
        idx: isInt(sv.idx) && sv.idx >= 0 ? sv.idx : 0,
        day: isInt(sv.day) ? sv.day : -1
      };
    }
  }
  if (raw.evidence && typeof raw.evidence === 'object') {
    for (var ek in raw.evidence) {
      var ev = raw.evidence[ek];
      if (!ev || typeof ev !== 'object') continue;
      d.evidence[ek] = {
        id: ek,
        title: typeof ev.title === 'string' ? ev.title : ek,
        source: typeof ev.source === 'string' ? ev.source : '',
        day: isInt(ev.day) ? ev.day : -1
      };
    }
  }
  if (raw.choices && typeof raw.choices === 'object') {
    for (var ck in raw.choices) if (typeof raw.choices[ck] === 'string') d.choices[ck] = raw.choices[ck];
  }
  if (raw.flags && typeof raw.flags === 'object') {
    for (var fk in raw.flags) {
      var fv = raw.flags[fk];
      if (typeof fv === 'boolean' || typeof fv === 'string') d.flags[fk] = fv;
      else if (isInt(fv)) d.flags[fk] = fv;
      else if (fv && typeof fv === 'object') {
        if (Array.isArray(fv)) d.flags[fk] = fv.filter(function (x) { return typeof x === 'string' || isInt(x); });
        else {
          var o = {};
          for (var ok in fv) if (typeof fv[ok] === 'boolean' || typeof fv[ok] === 'string' || isInt(fv[ok])) o[ok] = fv[ok];
          d.flags[fk] = o;
        }
      }
    }
  }
  d.lenaStance = (raw.lenaStance === 'cautious' || raw.lenaStance === 'public') ? raw.lenaStance : '';
  d.routeMethod = typeof raw.routeMethod === 'string' ? raw.routeMethod : '';
  d.rescueMethod = typeof raw.rescueMethod === 'string' ? raw.rescueMethod : '';
  d.evacPriority = typeof raw.evacPriority === 'string' ? raw.evacPriority : '';
  d.householdChoices = (raw.householdChoices && typeof raw.householdChoices === 'object') ? raw.householdChoices : {};
  d.support = (raw.support && typeof raw.support === 'object') ? raw.support : {};
  d.outcome = typeof raw.outcome === 'string' ? raw.outcome : '';
  return d;
}

function storyTask(id) {
  for (var i = 0; i < STORY_TASKS.length; i++) if (STORY_TASKS[i].id === id) return STORY_TASKS[i];
  return null;
}
function storySceneDef(id) { return STORY_SCENES[id] || null; }
function storyState() { if (!state.story) state.story = newStoryState(); return state.story; }

function storySceneProgress(id) {
  var st = storyState();
  if (!st.scenes[id] || typeof st.scenes[id] !== 'object') st.scenes[id] = { seen: false, skipped: false, idx: 0, day: -1 };
  var r = st.scenes[id];
  if (!isInt(r.idx) || r.idx < 0) r.idx = 0;
  return r;
}
function storySceneFinished(id) {
  var def = storySceneDef(id);
  if (!def) return false;
  var rec = storyState().scenes[id];
  /* 只读：判断一个场次演没演完，不该顺手在存档里留下一条场次记录。 */
  if (!rec) return false;
  return rec.idx >= (def.lines || []).length;
}
function storySceneSeen(id) { return !!storyState().scenes[id] && storyState().scenes[id].seen === true; }

/* 任务状态：实时判定解锁条件，不把「当时解锁」冻结成事实 */
function storyTaskStatus(id) {
  var t = storyTask(id);
  if (!t) return 'locked';
  var st = storyState();
  if (st.tasks[id] === 'done') return 'done';
  if (st.tasks[id] === 'active') return 'active';
  return storyTaskUnlocked(t) ? 'available' : 'locked';
}
function storyTaskUnlocked(t) {
  if (t.id === 'MQ1-P01') return true;
  if (t.id === 'MQ1-A01') {
    if (storyState().tasks['MQ1-P04'] !== 'done') return false;
    if (!storyEntryAchievement().ok) return false;
    return !!exploreState().city;
  }
  var prev = storyPrevTask(t.id);
  return !!prev && storyState().tasks[prev.id] === 'done';
}
function storyPrevTask(id) {
  for (var i = 0; i < STORY_TASKS.length; i++) if (STORY_TASKS[i].next === id) return STORY_TASKS[i];
  return null;
}

/* 入门成果：经营／工程／商旅／巡林任一，读既有真实账本，不新造事实 */
function storyEntryAchievement() {
  var routes = [];
  var plots = state.plots || {};
  var farmed = Object.keys(plots).some(function (k) {
    var p = plots[k];
    if (!p || typeof p !== 'object') return false;
    return !!p.crop || p.harvested === true;
  });
  var shipped = Object.keys(state.shipping || {}).some(function (k) { return (state.shipping[k] || 0) > 0; });
  if (farmed || shipped || (state.questProgress && state.questProgress[1] === 'done')) routes.push('经营');
  try {
    var rs = rookieState();
    if (rs.engineering >= ROOKIE_JOBS.engineering.steps.length) routes.push('工程');
    if (rs.trade >= ROOKIE_JOBS.trade.steps.length) routes.push('商旅');
    if (rs.patrol >= ROOKIE_JOBS.patrol.steps.length) routes.push('巡林');
  } catch (e) { /* 入门账本缺失时按没有成果算，不编造 */ }
  return { ok: routes.length > 0, routes: routes };
}

/* 老档：主线还没开始，但存档已经有真实进度 → 走补送信，不重做家园教程 */
function storyIsOldSave() {
  var st = storyState();
  if (st.started) return false;
  if (state.totalDay > 1) return true;
  if (state.bridgeRepaired) return true;
  if (Object.keys(state.questProgress || {}).some(function (k) { return state.questProgress[k] === 'done'; })) return true;
  if (Object.keys(state.plots || {}).length) return true;
  if (Object.keys(state.shipping || {}).length) return true;
  var e = exploreState();
  if (e.city || e.forest || e.mine) return true;
  return false;
}
function storyCityVisited() { return !!exploreState().city; }

/* 路线：未修桥时走镇内替代演出，任务一开始就把路线定下来，之后不再改 */
function storyRouteFor(t) {
  var key = 'route_' + t.id;
  var f = storyState().flags[key];
  if (f === 'mill' || f === 'town') return f;
  return (!state.bridgeRepaired && t.altScenes && t.altScenes.length) ? 'town' : 'mill';
}
function storyTaskScenes(t) {
  if (storyRouteFor(t) === 'town' && t.altScenes && t.altScenes.length) return t.altScenes.slice();
  return (t.scenes || []).slice();
}
function storyNextScene(t) {
  var scenes = storyTaskScenes(t);
  for (var i = 0; i < scenes.length; i++) if (!storySceneFinished(scenes[i])) return scenes[i];
  return null;
}

function storyRecordEvidence(id, source) {
  var st = storyState();
  if (st.evidence[id]) return false;
  var meta = STORY_EVIDENCE[id] || {};
  st.evidence[id] = { id: id, title: meta.title || id, source: source || meta.source || '', day: state.totalDay };
  markDirty();
  return true;
}
function storyHasEvidence(id) { return !!storyState().evidence[id]; }

function storyFlagObj(key) {
  var st = storyState();
  if (!st.flags[key] || typeof st.flags[key] !== 'object' || Array.isArray(st.flags[key])) st.flags[key] = {};
  return st.flags[key];
}
function storyFlagArr(key) {
  var st = storyState();
  if (!Array.isArray(st.flags[key])) st.flags[key] = [];
  return st.flags[key];
}

/* ============================================================
   场次演出
   ============================================================ */
function storyChoices() { return storyState().choices; }

function storyLineVisible(line) {
  if (!line.when) return true;
  try { return !!line.when(storyChoices()); } catch (e) { return true; }
}

function openStoryScene(sceneId) {
  var def = storySceneDef(sceneId);
  if (!def) { toast('这一段还没有实装。'); return; }
  var st = storyState();
  st.started = true;
  var t = storyTask(def.task);
  if (t && st.tasks[t.id] !== 'done') st.tasks[t.id] = 'active';
  if (t && !st.flags['route_' + t.id]) st.flags['route_' + t.id] = storyRouteFor(t);
  storySceneProgress(sceneId);
  openWindow({
    id: 'story_scene', kind: 'story', wide: true,
    title: sceneId + ' · ' + def.place + (def.time ? ' · ' + def.time : '') + (def.tag ? ' · ' + def.tag : ''),
    build: function (b) { buildStoryScene(b, sceneId); },
    actions: function () { return storySceneActions(sceneId); }
  });
}

function buildStoryScene(b, sceneId) {
  var def = storySceneDef(sceneId);
  if (!def) return;
  var rec = storySceneProgress(sceneId);
  var lines = def.lines || [];
  var t = storyTask(def.task);
  var head = el('div', 'story-head');
  head.appendChild(el('div', 'story-task-id', t ? t.id : ''));
  head.appendChild(el('div', 'story-task-title', t ? t.title : ''));
  head.appendChild(el('div', 'story-task-goal', t ? t.goal : ''));
  b.appendChild(head);
  var box = el('div', 'story-scene');
  for (var i = 0; i < lines.length && i <= rec.idx; i++) {
    var line = lines[i];
    if (!storyLineVisible(line)) continue;
    if (line.step) {
      if (i < rec.idx) { box.appendChild(storyStepDoneLine(line)); continue; }
      box.appendChild(buildStoryStep(line, sceneId));
      continue;
    }
    if (line.choice) {
      if (i < rec.idx) {
        var picked = storyChoices()[line.choice];
        box.appendChild(el('div', 'story-line story-choice-done', '（已选：' + storyChoiceText(line, picked) + '）'));
        continue;
      }
      box.appendChild(buildStoryChoice(line, sceneId));
      continue;
    }
    var row = el('div', 'story-line' + (line.who ? ' story-said' : ' story-narr'));
    if (line.who) row.appendChild(el('span', 'story-who', line.who));
    row.appendChild(el('span', 'story-text', line.text));
    box.appendChild(row);
  }
  b.appendChild(box);
  if (rec.idx >= lines.length) {
    b.appendChild(el('div', 'story-end', '—— 本场结束 ——'));
    if (def.memory) b.appendChild(el('p', 'muted', '回忆不改写世界日期、天气、体力和钱包；跳过的部分之后可以回看。'));
  }
}

function storyChoiceText(line, picked) {
  for (var i = 0; i < (line.options || []).length; i++) if (line.options[i].id === picked) return line.options[i].text;
  return picked || '';
}

function buildStoryChoice(line, sceneId) {
  var wrap = el('div', 'story-choice');
  wrap.appendChild(el('div', 'story-prompt', line.prompt || '请选择。'));
  var opts = el('div', 'story-options');
  (line.options || []).forEach(function (o) {
    opts.appendChild(mkBtn(o.text, 'story-opt', function () {
      storyState().choices[line.choice] = o.id;
      /* 对莱娜的表态在选下去的那一刻就生效，不等整段演完 */
      if (line.choice === 'a04_stance') storyState().lenaStance = o.id === 'A' ? 'cautious' : 'public';
      markDirty();
      storyAdvance(sceneId);
    }));
  });
  wrap.appendChild(opts);
  return wrap;
}

function storyStepDoneLine(line) {
  return el('div', 'story-line story-step-done', '〔已做过：' + (line.text || '') + '〕');
}

/* 互动步骤：items（按顺序点选） / overlay（叠图对照） / reception（花园接待） */
function buildStoryStep(line, sceneId) {
  var wrap = el('div', 'story-step');
  wrap.appendChild(el('div', 'story-prompt', line.text || ''));
  if (line.mode === 'items') wrap.appendChild(buildStoryItemsStep(line, sceneId));
  else if (line.mode === 'overlay') wrap.appendChild(buildStoryOverlayStep(line, sceneId));
  else if (line.mode === 'reception') wrap.appendChild(buildStoryReceptionStep(line, sceneId));
  else wrap.appendChild(el('p', 'muted', '这一步还没有实装。'));
  return wrap;
}

function buildStoryItemsStep(line, sceneId) {
  var key = 'step_' + line.step;
  var prog = storyFlagObj(key);
  var picked = Array.isArray(prog.picked) ? prog.picked : [];
  var order = line.order || line.picks || [];
  var wrap = el('div', 'story-items');
  if (line.hint) wrap.appendChild(el('p', 'muted', line.hint));
  var row = el('div', 'story-picks');
  (line.picks || []).forEach(function (p) {
    var done = picked.indexOf(p) >= 0;
    var btn = mkBtn(p, 'story-pick' + (done ? ' on' : ''), function () {
      var cur = storyFlagObj(key);
      var list = Array.isArray(cur.picked) ? cur.picked : [];
      if (list.indexOf(p) >= 0) return;
      var next = order[list.length];
      if (next !== p) {
        cur.picked = [];
        toast('对不上：' + p + '不是这一步要的那一样。');
        refreshWindow();
        return;
      }
      list.push(p);
      cur.picked = list;
      markDirty();
      if (list.length >= order.length) toast('三处参照都对上了。');
      refreshWindow();
    });
    row.appendChild(btn);
  });
  wrap.appendChild(row);
  if (picked.length >= order.length) {
    wrap.appendChild(mkBtn(line.confirm || '确认', 'primary', function () { storyAdvance(sceneId); }));
  } else {
    wrap.appendChild(el('p', 'muted', '已确认 ' + picked.length + ' / ' + order.length + '。'));
  }
  return wrap;
}

function buildStoryOverlayStep(line, sceneId) {
  var key = 'step_' + line.step;
  var prog = storyFlagObj(key);
  var matched = prog.matched && typeof prog.matched === 'object' ? prog.matched : {};
  var answered = prog.answered === 'done';
  var wrap = el('div', 'story-overlay');
  wrap.appendChild(el('p', 'muted', '艾琳把两册图并排摊开：旧图在左，新版在右。参照对上了，才谈得上改了什么。'));
  (line.refs || []).forEach(function (ref) {
    var row = el('div', 'story-ref');
    row.appendChild(el('span', 'story-ref-name', ref.name));
    if (matched[ref.id]) {
      row.appendChild(el('span', 'story-ref-ok', ref.note));
    } else {
      var opts = el('div', 'story-ref-opts');
      [['old', '只在旧图'], ['new', '只在新版'], ['both', '两张都有']].forEach(function (o) {
        opts.appendChild(mkBtn(o[1], 'sm', function () {
          if (o[0] !== ref.answer) { toast('再看看：' + ref.name + '在两张图上并不像你想的那样。'); return; }
          var p = storyFlagObj(key);
          p.matched = p.matched && typeof p.matched === 'object' ? p.matched : {};
          p.matched[ref.id] = true;
          markDirty();
          refreshWindow();
        }));
      });
      row.appendChild(opts);
    }
    wrap.appendChild(row);
  });
  var allMatched = (line.refs || []).every(function (r) { return matched[r.id]; });
  if (allMatched && !answered) {
    var q = el('div', 'story-choice');
    q.appendChild(el('div', 'story-prompt', line.question || '请判断。'));
    var opts2 = el('div', 'story-options');
    (line.options || []).forEach(function (o) {
      opts2.appendChild(mkBtn(o.text, 'story-opt', function () {
        if (o.id !== line.answer) { toast(line.answerNote || '诺尔说得对：能确认它写了什么，不能替它证明什么。'); return; }
        var p = storyFlagObj(key);
        p.answered = 'done';
        markDirty();
        storyAdvance(sceneId);
      }));
    });
    q.appendChild(opts2);
    wrap.appendChild(q);
  } else if (answered) {
    wrap.appendChild(el('div', 'story-step-done', '〔已判断：' + (line.answerNote || '已得出结论') + '〕'));
  }
  return wrap;
}

function buildStoryReceptionStep(line, sceneId) {
  var key = 'step_' + line.step;
  var observed = storyFlagObj(key + '_observed');
  var approached = storyFlagArr(key + '_approached');
  var mode = storyState().flags[key + '_mode'];
  var wrap = el('div', 'story-reception');
  wrap.appendChild(el('p', 'muted', '花园里没有人在催你。塞琳只说：想问谁，先自己看。'));
  (line.guests || []).forEach(function (g) {
    var card = el('div', 'story-guest');
    card.appendChild(el('div', 'story-guest-name', g.name));
    card.appendChild(el('div', 'story-guest-hint', g.hint));
    if (observed[g.id]) {
      card.appendChild(el('div', 'story-guest-ok', g.reveals));
      if (approached.indexOf(g.id) < 0) {
        var need = g.needEvidence && !storyHasEvidence(g.needEvidence);
        if (need) card.appendChild(el('p', 'muted', '他还不会开口：先让他看到你抄下来的索引。'));
        else card.appendChild(mkBtn(approached.length ? '再问这一位' : '先请他开口', 'sm', function () {
          var arr = storyFlagArr(key + '_approached');
          if (arr.indexOf(g.id) < 0) arr.push(g.id);
          storyRecordEvidence(g.evidence, 'S013 · 花园接待');
          markDirty();
          refreshWindow();
        }));
      } else {
        card.appendChild(el('div', 'story-step-done', '〔已问过〕'));
      }
    } else {
      card.appendChild(mkBtn('先看看他站哪儿', 'sm', function () {
        var p = storyFlagObj(key + '_observed');
        p[g.id] = true;
        markDirty();
        refreshWindow();
      }));
    }
    wrap.appendChild(card);
  });
  var allObserved = (line.guests || []).every(function (g) { return observed[g.id]; });
  if (allObserved && approached.length < (line.minApproach || 1)) {
    wrap.appendChild(el('p', 'muted', '至少问过两个人，才算摸清谁愿意开口、谁只肯转述。'));
  } else if (allObserved && approached.length >= (line.minApproach || 1) && !mode) {
    var q = el('div', 'story-choice');
    q.appendChild(el('div', 'story-prompt', '接下来，你打算当着众人问，还是把这一位单独请到步道？'));
    var opts = el('div', 'story-options');
    opts.appendChild(mkBtn('当着众人问 · 公开', 'story-opt', function () {
      storyState().flags[key + '_mode'] = 'public';
      markDirty(); refreshWindow();
    }));
    opts.appendChild(mkBtn('单独请到步道 · 私谈', 'story-opt', function () {
      storyState().flags[key + '_mode'] = 'private';
      markDirty(); refreshWindow();
    }));
    q.appendChild(opts);
    wrap.appendChild(q);
  } else if (mode) {
    wrap.appendChild(el('div', 'story-step-done', '〔已定：' + (mode === 'public' ? '当众问' : '单独私谈') + '〕'));
    wrap.appendChild(mkBtn('这一段到此为止', 'primary', function () { storyAdvance(sceneId); }));
  }
  return wrap;
}

function storyAdvance(sceneId) {
  var rec = storySceneProgress(sceneId);
  var def = storySceneDef(sceneId);
  var lines = (def && def.lines) || [];
  var next = (rec.idx || 0) + 1;
  /* 跳过因分支而隐藏的台词：选择定了以后，另一句回复不占玩家的点击。 */
  while (next < lines.length && !storyLineVisible(lines[next])) next++;
  rec.idx = next > lines.length ? lines.length : next;
  markDirty();
  refreshWindow();
}

function storySceneActions(sceneId) {
  var def = storySceneDef(sceneId);
  if (!def) return [];
  var rec = storySceneProgress(sceneId);
  var lines = def.lines || [];
  if (rec.idx < lines.length) {
    var cur = lines[rec.idx];
    if (cur && (cur.step || cur.choice)) return [];
    return [{ label: '继续', kind: 'primary', close: false, onClick: function () { storyAdvance(sceneId); } }];
  }
  var chain = def.chain === 'memory';
  return [
    { label: chain ? '回到门前' : '继续', kind: 'primary', close: false, onClick: function () { storyFinishScene(sceneId); } },
    { label: '先停在这里', kind: 'ghost', close: true }
  ];
}

function storyFinishScene(sceneId) {
  var def = storySceneDef(sceneId);
  if (!def) return;
  var rec = storySceneProgress(sceneId);
  rec.seen = true;
  rec.day = state.totalDay;
  (def.evidence || []).forEach(function (evId) { storyRecordEvidence(evId, sceneId + ' · ' + def.where); });
  markDirty();
  if (def.chain === 'memory') {
    var mem = ['S000A', 'S000B'];
    var i = mem.indexOf(sceneId);
    var nextMem = i >= 0 ? mem[i + 1] : null;
    if (nextMem && !storySceneFinished(nextMem)) { openStoryScene(nextMem); return; }
    storyState().flags.memoryDone = true;
    saveNow();
    openStoryMemoryDone();
    return;
  }
  var t = storyTask(def.task);
  if (!t) { closeWindow(); return; }
  var scenes = storyTaskScenes(t);
  var idx = scenes.indexOf(sceneId);
  var next = idx >= 0 ? scenes[idx + 1] : null;
  if (next) {
    var nextDef = storySceneDef(next);
    /* 下一场在别的场景：不替玩家瞬移，写清地点让玩家自己走过去 */
    if (nextDef && storySceneLoc(next) !== storySceneLoc(sceneId) && storySceneLoc(next) !== 'memory') {
      openStoryNextPlace(t, next, nextDef);
      return;
    }
    openStoryScene(next);
    return;
  }
  storyCompleteTask(t);
}

function storyCompleteTask(t) {
  var st = storyState();
  if (st.tasks[t.id] === 'done') return;
  st.tasks[t.id] = 'done';
  if (t.id === 'MQ1-A04') {
    var stance = st.choices.a04_stance;
    if (stance === 'A') st.lenaStance = 'cautious';
    else if (stance === 'B') st.lenaStance = 'public';
  }
  grantCharExpOnce('story.task.' + t.id, t.exp || CHAR_EXP.quest, 'quest');
  questLogPush('主线 ' + t.id + '《' + t.title + '》已完成。' + (t.next ? ' 下一段：' + storyTaskTitle(t.next) : ''));
  saveNow();
  openStoryTaskDone(t);
}

function storyTaskTitle(id) {
  var t = storyTask(id);
  return t ? (t.id + '《' + t.title + '》') : '后续章节';
}

function openStoryTaskDone(t) {
  var next = t.next ? storyTask(t.next) : null;
  var nextStatus = next ? storyTaskStatus(next.id) : null;
  var lines = [];
  lines.push('本段结束：' + t.id + '《' + t.title + '》');
  if (next) {
    lines.push('下一段：' + next.id + '《' + next.title + '》');
    if (nextStatus === 'locked') lines.push('尚未解锁：' + storyLockReason(next));
    else lines.push('可以去：' + storyNextStepText(next.id));
  } else {
    lines.push('第一部主线到此为止，后面的章节还在制作中。');
  }
  openWindow({
    id: 'story_done', kind: 'story', title: '一段走完了',
    build: function (b) {
      b.appendChild(el('div', 'section-title', '本段完成'));
      lines.forEach(function (l) { b.appendChild(el('p', null, l)); });
      var ev = Object.keys(storyState().evidence);
      if (ev.length) {
        b.appendChild(el('div', 'section-title', '已登记的证据'));
        ev.forEach(function (k) {
          var e = storyState().evidence[k];
          b.appendChild(el('div', 'story-evidence', '· ' + e.title + '（' + e.source + '）'));
        });
      }
    },
    actions: [
      { label: '回到主线', kind: 'primary', close: false, onClick: function () { openStoryLog(); } },
      { label: '关闭', kind: 'ghost', close: true }
    ]
  });
}

/* ============================================================
   入口面板
   ============================================================ */
function openStoryEntry(it) {
  var d = it.story || {};
  var t = storyTask(d.task);
  if (!t) { toast('这一段还没有实装。'); return; }
  /* 老档补送信：主线还没开始，但玩家已经在这座农场生活过一段时间 */
  if (d.supplement && !storyState().started && storyIsOldSave() && storyTaskStatus(d.supplement) !== 'done') {
    openStorySupplement(d.supplement, it);
    return;
  }
  var status = storyTaskStatus(d.task);
  if (status === 'locked') { openStoryLocked(t); return; }
  var sid = d.storyScene;
  var chain = storyTaskScenes(t);
  if (sid && chain.indexOf(sid) < 0) { openStoryRoutePanel(t, sid); return; }
  if (sid) {
    /* 场次有先后：前面的还没演，这里就只是把顺序说清楚，不跳过 */
    var at = chain.indexOf(sid);
    for (var i = 0; i < at; i++) {
      if (!storySceneFinished(chain[i])) {
        var prevDef = storySceneDef(chain[i]);
        openStoryOrderPanel(t, chain[i], prevDef, sid);
        return;
      }
    }
  }
  if (sid && storySceneFinished(sid)) { openStoryReview(t); return; }
  if (t.id === 'MQ1-P01' && sid === 'S001' && !storyState().flags.memoryDone && !storyState().flags.memorySkipped) {
    openStoryMemoryOffer(t);
    return;
  }
  if (sid) { openStoryScene(sid); return; }
  var next = storyNextScene(t);
  if (!next) { storyCompleteTask(t); return; }
  openStoryScene(next);
}

/* 这一场不属于当前路线（例如桥还没修，就没有磨坊那条线） */
function openStoryRoutePanel(t, sid) {
  var def = storySceneDef(sid);
  openWindow({
    id: 'story_route', kind: 'story', title: t.id + '《' + t.title + '》',
    build: function (b) {
      b.appendChild(el('p', null, '这一段属于另一条路线：' + sid + '（' + (def ? def.where : '') + '）。'));
      b.appendChild(el('p', null, '你眼下走的是：' + storyRouteText(t) + '。'));
      b.appendChild(el('p', 'muted', '两个入口拿到的是同一份索引与同一个奖励键，不会重复发放。'));
    },
    actions: [
      { label: '看看当前这条线', kind: 'primary', close: false, onClick: function () { openStoryTaskPanel(t); } },
      { label: '关闭', kind: 'ghost', close: true }
    ]
  });
}
function storyRouteText(t) {
  var chain = storyTaskScenes(t);
  var names = chain.map(function (sid) { var d = storySceneDef(sid); return d ? d.where : sid; });
  return names.join(' → ');
}

/* 顺序不对：告诉玩家先演哪一场，不让玩家跳着来 */
function openStoryOrderPanel(t, prevId, prevDef, wantId) {
  var wantDef = storySceneDef(wantId);
  var prevEntry = storyEntryForScene(prevId);
  openWindow({
    id: 'story_order', kind: 'story', title: t.id + '《' + t.title + '》',
    build: function (b) {
      b.appendChild(el('p', null, '这场要先走前一步。'));
      b.appendChild(el('div', 'section-title', '先演这一场'));
      b.appendChild(el('p', null, prevId + ' · ' + (prevDef ? prevDef.where : '')));
      if (prevEntry) b.appendChild(el('p', 'muted', '到了那儿，按 E 打开「' + prevEntry.label + '」。'));
      b.appendChild(el('p', 'muted', '之后才能演：' + wantId + (wantDef ? '（' + wantDef.where + '）' : '') + '。'));
    },
    actions: [
      { label: '打开地图', kind: 'primary', close: false, onClick: function () { openWorldMap(); } },
      { label: '关闭', kind: 'ghost', close: true }
    ]
  });
}

function openStoryTaskPanel(t) {
  var next = storyNextScene(t);
  var def = next ? storySceneDef(next) : null;
  var entry = next ? storyEntryForScene(next) : null;
  openWindow({
    id: 'story_task', kind: 'story', title: t.id + '《' + t.title + '》',
    build: function (b) {
      b.appendChild(el('p', null, t.goal));
      b.appendChild(el('div', 'section-title', '下一步'));
      b.appendChild(el('p', null, next ? (next + ' · ' + (def ? def.where : '')) : '本段已演完。'));
      if (entry) b.appendChild(el('p', 'muted', '走到「' + entry.label + '」按 E 就能继续。'));
      b.appendChild(el('div', 'section-title', '本段的场次'));
      storyTaskScenes(t).forEach(function (sid) {
        var d = storySceneDef(sid);
        if (!d) return;
        b.appendChild(el('div', 'story-evidence', '· ' + sid + ' · ' + d.where + (storySceneSeen(sid) ? '（已演）' : '')));
      });
    },
    actions: [
      { label: '打开地图', kind: 'primary', close: false, onClick: function () { openWorldMap(); } },
      { label: '关闭', kind: 'ghost', close: true }
    ]
  });
}

/* 下一场在别的场景：不替玩家瞬移，把地点写清楚，让玩家自己走过去 */
function openStoryNextPlace(t, sid, def) {
  var entry = storyEntryForScene(sid);
  openWindow({
    id: 'story_next_place', kind: 'story', title: '下一场在别处',
    build: function (b) {
      b.appendChild(el('p', null, '本场到此结束。下一场：' + sid + '《' + def.place + '》。'));
      b.appendChild(el('div', 'section-title', '去哪儿'));
      b.appendChild(el('p', null, def.where));
      b.appendChild(el('p', 'muted', entry
        ? ('到了那儿，按 E 打开「' + entry.label + '」。这段路不传送，慢慢走。')
        : '按 M 打开地图找路。'));
    },
    actions: [
      { label: '打开地图', kind: 'primary', close: false, onClick: function () { openWorldMap(); } },
      { label: '先停在这里', kind: 'ghost', close: true }
    ]
  });
}

function openStoryLocked(t) {
  openWindow({
    id: 'story_locked', kind: 'story', title: t.id + '《' + t.title + '》',
    build: function (b) {
      b.appendChild(el('p', null, t.goal));
      b.appendChild(el('div', 'section-title', '现在的门槛'));
      b.appendChild(el('p', null, storyLockReason(t)));
      b.appendChild(el('p', 'muted', '门槛满足后，这里会自己开。不需要重做已经完成的事。'));
    },
    actions: [{ label: '知道了', kind: 'ghost', close: true }]
  });
}

function storyLockReason(t) {
  if (t.id === 'MQ1-A01') {
    if (storyState().tasks['MQ1-P04'] !== 'done') return '先完成序章：' + storyTaskTitle('MQ1-P04') + '。';
    var ach = storyEntryAchievement();
    if (!ach.ok) return '先在白蔷薇开始生活：照料一格田、完成一份小镇工作，或修好东侧小桥（经营／工程／商旅／巡林任一）。';
    if (!exploreState().city) return '城市通行是明确的社会门槛：先修好东侧小桥，再办 150 金的白蔷薇城通行证。缺钱可以先做小镇工作。';
    return '条件已满足。';
  }
  var prev = storyPrevTask(t.id);
  if (prev) return '先完成' + storyTaskTitle(prev.id) + '。';
  return '条件未满足。';
}

function openStoryMemoryOffer(t) {
  openWindow({
    id: 'story_memory_offer', kind: 'story', title: '一封信，一处屋檐',
    build: function (b) {
      b.appendChild(el('p', null, '芽芽把门牌旁的藤拨开。你手里的信折过很多次，边角已经起毛。'));
      b.appendChild(el('p', null, '信到之前的事，你自己记得一部分：路上那座棚檐，那个替你想办法的测绘师。'));
      b.appendChild(el('p', 'muted', '这段回忆约 3—5 分钟，可以跳过。跳过的部分之后仍能回看；世界日期、天气、体力和钱包都不会因此变化。'));
    },
    actions: [
      { label: '先看那段路（回忆）', kind: 'primary', close: false, onClick: function () { openStoryScene('S000A'); } },
      { label: '跳过回忆，直接看信', kind: 'sm', close: false, onClick: function () {
        storyState().flags.memorySkipped = true;
        storyState().scenes['S000A'] = { seen: false, skipped: true, idx: 0, day: state.totalDay };
        storyState().scenes['S000B'] = { seen: false, skipped: true, idx: 0, day: state.totalDay };
        markDirty();
        openStoryScene('S001');
      } },
      { label: '先不开始', kind: 'ghost', close: true }
    ]
  });
}

function openStoryMemoryDone() {
  openWindow({
    id: 'story_memory_done', kind: 'story', title: '回到门前',
    build: function (b) {
      b.appendChild(el('p', null, '雨停了。扣带系得比你自己打的好看一点。'));
      b.appendChild(el('p', 'muted', '这段回忆可以在主线日志里回看。'));
    },
    actions: [
      { label: '继续 · 看那封信', kind: 'primary', close: false, onClick: function () { openStoryScene('S001'); } },
      { label: '先停在这里', kind: 'ghost', close: true }
    ]
  });
}

function openStorySupplement(taskId, it) {
  var t = storyTask(taskId);
  openWindow({
    id: 'story_supplement', kind: 'story', title: '补送的信',
    build: function (b) {
      b.appendChild(el('p', null, it && it.label === '分信柜旁的旧邮路'
        ? '小翎从退信堆里抽出一封：「转来过两次，总算送到你手里。」'
        : '芽芽把小翎托她补送的信递过来：「说是给你的，路上压了两回。」'));
      b.appendChild(el('p', null, '信上署名是伊文。他介绍白蔷薇那处空着的农场，说等最后一条路画完就回来。'));
      b.appendChild(el('p', 'muted', '你已经在这里住了一段时间，钥匙和住处不重发；家园教程也不会重做。'));
    },
    actions: [
      { label: '拆开信', kind: 'primary', close: false, onClick: function () {
        storyState().flags.memorySkipped = true;
        markDirty();
        openStoryScene('S001');
      } },
      { label: '先看那段路（回忆）', kind: 'sm', close: false, onClick: function () { openStoryScene('S000A'); } },
      { label: '先收着', kind: 'ghost', close: true }
    ]
  });
}

function openStoryReview(t) {
  var scenes = storyTaskScenes(t);
  openWindow({
    id: 'story_review', kind: 'story', wide: true, title: t.id + '《' + t.title + '》· 已完成',
    build: function (b) {
      b.appendChild(el('p', null, t.goal));
      b.appendChild(el('div', 'section-title', '可以回看的场次'));
      scenes.forEach(function (sid) {
        var def = storySceneDef(sid);
        if (!def) return;
        b.appendChild(mkBtn('S ' + sid + ' · ' + def.place + (storySceneSeen(sid) ? '' : '（未演）'), 'sm', function () {
          openStoryScene(sid);
        }));
      });
      if (t.memory && t.memory.length) {
        b.appendChild(el('div', 'section-title', '回忆'));
        t.memory.forEach(function (sid) {
          var def = storySceneDef(sid);
          if (!def) return;
          b.appendChild(mkBtn('S ' + sid + ' · ' + def.place, 'sm', function () { openStoryScene(sid); }));
        });
      }
    },
    actions: [{ label: '关闭', kind: 'ghost', close: true }]
  });
}

/* ============================================================
   主线日志
   ============================================================ */
function storyNextStepText(taskId) {
  var t = storyTask(taskId);
  if (!t) return '后续章节。';
  var status = storyTaskStatus(taskId);
  if (status === 'done') return '已完成 · ' + t.goal;
  if (status === 'locked') return '未解锁 · ' + storyLockReason(t);
  var next = storyNextScene(t);
  if (!next) return '本段已演完，等结算。';
  var def = storySceneDef(next);
  var entry = storyEntryForScene(next);
  return '下一场 ' + next + ' · ' + (def ? def.where : '') + (entry ? '（按 E 打开「' + entry.label + '」）' : '');
}

function openStoryLog() {
  openWindow({
    id: 'story_log', kind: 'story', wide: true, title: '主线 · 长风有归处（第一幕切片）',
    build: function (b) {
      b.appendChild(el('p', 'muted', '第九版第一部主线。M0 切片实装序章与第一幕共 9 个任务；后续章节仍在制作中，这里如实写「未实装」。'));
      var st = storyState();
      var curAct = 0;
      STORY_TASKS.forEach(function (t) {
        if (t.act !== curAct) {
          curAct = t.act;
          b.appendChild(el('div', 'section-title', t.actName));
        }
        var status = storyTaskStatus(t.id);
        var box = el('div', 'panel-box quest' + (status === 'done' ? ' done' : status === 'locked' ? ' locked' : ''));
        var head = el('div', 'row between');
        head.appendChild(el('div', 'quest-name', t.id + '. ' + t.title));
        head.appendChild(el('span', 'req-chip ' + (status === 'done' ? 'ok' : status === 'locked' ? 'no' : ''),
          status === 'done' ? '已完成' : status === 'locked' ? '未解锁' : '进行中'));
        box.appendChild(head);
        box.appendChild(el('div', 'item-desc', t.goal));
        box.appendChild(el('div', 'quest-next', '下一步：' + storyNextStepText(t.id)));
        if (status !== 'locked' && status !== 'done') {
          var acts = el('div', 'item-actions');
          acts.appendChild(mkBtn('继续这一段', 'primary sm', function () {
            var next = storyNextScene(t);
            if (!next) { openStoryReview(t); return; }
            var loc = storySceneLoc(next);
            /* 下一场不在眼前就先把地点说清楚，不替玩家瞬移 */
            if (loc && loc !== 'memory' && loc !== state.sceneId) { openStoryTaskPanel(t); return; }
            openStoryScene(next);
          }));
          box.appendChild(acts);
        }
        if (status === 'done') {
          var acts2 = el('div', 'item-actions');
          acts2.appendChild(mkBtn('回看场次', 'sm', function () { openStoryReview(t); }));
          box.appendChild(acts2);
        }
        b.appendChild(box);
      });
      var evs = Object.keys(st.evidence);
      b.appendChild(el('div', 'section-title', '已登记的证据（' + evs.length + '）'));
      if (!evs.length) b.appendChild(el('div', 'empty-note', '还没有登记任何证据。'));
      evs.forEach(function (k) {
        var e = st.evidence[k];
        b.appendChild(el('div', 'story-evidence', '· ' + e.title + '（' + e.source + '）'));
      });
      appendSegmentLedger(b, farmPlanState());
      b.appendChild(mkBtn('分段旅行与照料安排', 'sm', openFarmSchedulePanel));
      if (st.lenaStance) {
        b.appendChild(el('div', 'section-title', '记录'));
        b.appendChild(el('div', 'story-evidence', '· 对莱娜的表态：' + (st.lenaStance === 'cautious' ? '谨慎 · 先写进申请，核对原件' : '公开 · 让受影响的人也知道在查')));
      }
      b.appendChild(el('div', 'section-title', '回忆'));
      var p01 = storyTask('MQ1-P01');
      (p01.memory || []).forEach(function (sid) {
        var def = storySceneDef(sid);
        if (!def) return;
        b.appendChild(mkBtn('S ' + sid + ' · ' + def.place + (storySceneSeen(sid) ? ' · 已演' : ' · 未演'), 'sm', function () { openStoryScene(sid); }));
      });
    },
    actions: [{ label: '关闭', kind: 'ghost', close: true }]
  });
}

/* 今日安排与委托日志的接线 */
function storyTodayLine() {
  var i, t, s;
  for (i = 0; i < STORY_TASKS.length; i++) {
    t = STORY_TASKS[i];
    s = storyTaskStatus(t.id);
    if (s === 'active' || s === 'available') {
      var scene = storyNextScene(t);
      var where = scene ? (storySceneDef(scene) || {}).where : '';
      return { tier: 'soon', tag: '主线', text: t.id + ' ' + t.title + (where ? ' · ' + where : ''), open: openStoryLog };
    }
  }
  /* 一段都锁着：把最靠前的那道门槛说清楚，别让玩家对着空日志猜 */
  for (i = 0; i < STORY_TASKS.length; i++) {
    t = STORY_TASKS[i];
    if (storyTaskStatus(t.id) === 'locked') {
      return { tier: 'later', tag: '主线', text: '主线 ' + t.id + ' · ' + storyLockReason(t), open: openStoryLog };
    }
  }
  return null;
}

function appendStoryQuestSection(b) {
  var line = storyTodayLine();
  b.appendChild(el('div', 'section-title', '第一部主线 · 长风有归处'));
  if (!line) {
    b.appendChild(el('div', 'empty-note', '主线尚未开始：去苔芽农场的农舍门牌旁，芽芽留给你的那封信就在那里。'));
  } else {
    b.appendChild(el('div', 'quest-next', line.text));
    b.appendChild(mkBtn('打开主线日志', 'sm', openStoryLog));
  }
}

