function exploreState(){if(!state.exploration)state.exploration=normalizeExploration();var e=state.exploration;if(!e.cityStories)e.cityStories={};if(!Number.isFinite(e.cityReputation))e.cityReputation=0;if(typeof e.smithCoupon!=='boolean')e.smithCoupon=false;return e;}
/* --- R5-0 票据批次账本 ---
 * 只回答两件事：这张票是哪天拿到的（公债满期要用），以及这笔钱走过哪条路。
 * 批次与背包数量对不上时以背包为准多退少补；查不到来源的老票据按已满期处理，
 * 这样旧档既不会被卡住，也不会因为缺记录而凭空多出兑付资格。 */
function billLotsSync(item){
  var q=BILL_QUOTES[item];if(!q)return 0;
  var e=exploreState();if(!Array.isArray(e.billLots))e.billLots=[];
  var lots=e.billLots,i,sum=0,L;
  for(i=0;i<lots.length;i++){L=lots[i];
    if(!L||L.item!==item||!Number.isFinite(L.qty)||!Number.isFinite(L.day)||L.qty<=0||L.day<0){lots.splice(i--,1);continue;}
    L.qty=Math.floor(L.qty);L.day=Math.floor(L.day);sum+=L.qty;}
  var held=invCount(item);
  while(sum>held&&lots.length){L=lots[lots.length-1];var cut=Math.min(L.qty,sum-held);L.qty-=cut;sum-=cut;if(L.qty<=0)lots.pop();}
  if(sum<held)lots.push({item:item,qty:held-sum,day:0});
  return sum;
}
/* 现在就能兑付的张数：只算已满 term 的批次，不足就少给，绝不预支 */
function billRedeemable(item){
  var q=BILL_QUOTES[item];if(!q)return 0;
  billLotsSync(item);
  var held=invCount(item);if(!q.term)return held;
  var n=0;exploreState().billLots.forEach(function(L){if(L.item===item&&state.totalDay-L.day>=q.term)n+=L.qty;});
  return Math.max(0,Math.min(n,held));
}
/* 未满期票据还要等几天；没有未满期的返回 0 */
function billMaturityWait(item){
  var q=BILL_QUOTES[item];if(!q||!q.term)return 0;
  billLotsSync(item);var soon=-1;
  exploreState().billLots.forEach(function(L){if(L.item!==item)return;var left=q.term-(state.totalDay-L.day);if(left>0&&(soon<0||left<soon))soon=left;});
  return soon<0?0:soon;
}
/* 票据流水：来源、成本、处置方式和事务 ID 都留痕 */
function billTxLog(item,kind,amt,src){
  var e=exploreState();if(!Array.isArray(e.billTx))e.billTx=[];
  e.billTx.push({tx:'bill:'+kind+':'+item+':d'+state.totalDay+':#'+(e.billTx.length+1),
    item:item,kind:kind,amt:Math.round(amt),day:state.totalDay,src:src||(BILL_QUOTES[item]&&BILL_QUOTES[item].source)||''});
  if(e.billTx.length>40)e.billTx.splice(0,e.billTx.length-40);
}
function exploreNode(sc,x,y){var def=EXPLORE_NODES[sc]&&EXPLORE_NODES[sc][key2(x,y)];if(!def)return null;
 if(sc==='mine2'&&x>20&&y>11&&y<17&&!mineWorks().pump)return null;
 var e=exploreState(),key=sc+':'+key2(x,y),saved=e.nodes[key];
 if(!saved){saved=e.nodes[key]={hp:def.hp,day:state.totalDay};}
 var delay=def.regen||(def.type==='forage'?1:3);
 if(saved.hp<=0&&state.totalDay-saved.day>=delay&&!(state.sceneId===sc&&state.player.x===x&&state.player.y===y)){saved.hp=def.hp;}
 return {def:def,saved:saved};
}
function gatherExplore(tool,x,y){
 var n=exploreNode(state.sceneId,x,y);if(!n){toast('这里没有可采集的资源。');return false;}
 var expected=n.def.type==='tree'?'axe':n.def.type==='stone'?'pickaxe':'harvest';
 if(tool!==expected){toast('请用'+(expected==='axe'?'斧头':expected==='pickaxe'?'镐子':'收获篮')+'采集'+itemName(n.def.item)+'。');return false;}
 if(n.saved.hp<=0){toast('这里的资源尚未恢复：蘑菇隔天、木材和矿石 3 天、硬木 5 天。');return false;}
 var cost=expected==='harvest'?2:CFG.energyCost[expected],damage=exploreState().tools&&expected!=='harvest'?2:1;
 if(n.saved.hp<=damage&&!bagAccepts(n.def.item,n.def.qty)){toast('背包满了，先整理一下。');return false;}
 if(!charSpendEnergy(cost))return false;
 n.saved.hp=Math.max(0,n.saved.hp-damage);
 if(n.saved.hp===0){grantCharExpDaily('gather',CHAR_EXP.harvest);invAdd(n.def.item,n.def.qty);n.saved.day=state.totalDay;toast('获得'+itemName(n.def.item)+' ×'+n.def.qty+'。');}
 else toast(itemName(n.def.item)+'：还需 '+Math.ceil(n.saved.hp/damage)+' 次。');
 addParticle(x,y,expected==='axe'?'wood':'stone');Audio2.play(expected==='axe'?'chop':'breakrock');markDirty();refreshHud();refreshHotbar();return true;
}
function payExplore(cost){
 for(var k in cost)if(!Number.isFinite(cost[k])||cost[k]<0){toast('账目有误，这笔交易没有执行。');return false;}
 for(var k in cost)if((k==='coins'?state.coins:invCount(k))<cost[k]){toast('材料不足，需要 '+Object.keys(cost).map(function(id){return(id==='coins'?'金币':itemName(id))+' ×'+cost[id];}).join('、'));return false;}
 for(var k in cost)if(k==='coins')state.coins-=cost[k];else invRemove(k,cost[k]);return true;
}
