/* --- 装饰（确定性生成，刷新不变） --- */
var decorCache = {};
function getDecor(sceneId) {
  if (decorCache[sceneId]) return decorCache[sceneId];
  var map = MAPS[sceneId];
  var out = [];
  var seed = 0;
  for (var i = 0; i < sceneId.length; i++) seed = (seed * 31 + sceneId.charCodeAt(i)) | 0;
  var rnd = mulberry32(seed);
  for (var y = 0; y < map.h; y++) {
    for (var x = 0; x < map.w; x++) {
      if (map.t[x][y] !== T_GRASS) continue;
      var r = rnd();
      if (r > 0.86) out.push({ t: 'tuft', x: x, y: y, v: Math.floor(rnd() * 3) });
      else if (r > 0.80) out.push({ t: 'flower', x: x, y: y, v: Math.floor(rnd() * 3) });
    }
  }
  if (map.decor) map.decor.forEach(function (d) { out.push(d); });
  decorCache[sceneId] = out;
  return out;
}

function terrainAt(sceneId, x, y) {
  if(state&&sceneId==='mine2'&&mineWorkTile(x,y))return mineWorkBlocked(x,y)?T_POND:T_PATH;
  var map = MAPS[sceneId];
  if (x < 0 || y < 0 || x >= map.w || y >= map.h) return T_BUILDING;
  return map.t[x][y];
}
function isSolidStatic(sceneId, x, y) {
  if(state&&sceneId==='mine2'&&mineWorkTile(x,y))return mineWorkBlocked(x,y);
  var map = MAPS[sceneId];
  if (x < 0 || y < 0 || x >= map.w || y >= map.h) return true;
  return map.solid[x][y] === 1;
}

/* 完整碰撞（静态 + 资源节点 + 设备 + 室内家具 + 桥状态） */
function isSolid(sceneId, x, y) {
  if (isSolidStatic(sceneId, x, y)) {
    if (sceneId === 'town' && state.bridgeRepaired && x >= 26 && x <= 29 && y >= 10 && y <= 11) return false;
    return true;
  }
  var en=exploreNode(sceneId,x,y);if(en&&en.saved.hp>0&&en.def.type!=='forage')return true;
  if (sceneId === 'house' && houseFurnitureAt(x, y)) return true;
  if (INTERIOR_FURNITURE[sceneId] && interiorFurnitureAt(sceneId, x, y)) return true;
  if (sceneId === 'farm') {
    var n = state.resourceNodes[key2(x, y)];
    if (n && n.active && (n.type === 'tree' || n.type === 'stone')) return true;
  }
  if (sceneId === 'farm') {
    for (var i = 0; i < state.structures.length; i++) {
      var s = state.structures[i];
      if (s.x === x && s.y === y) return true;
    }
  }
  return false;
}

function isWater(sceneId, x, y) {
  var t = terrainAt(sceneId, x, y);
  return t === T_WATER || t === T_POND;
}

/* --- 四方向 BFS 寻路 --- */
function findPath(sceneId, sx, sy, tx, ty) {
  if (sx === tx && sy === ty) return [];
  if (isSolid(sceneId, tx, ty)) return null;
  var map = MAPS[sceneId];
  var prev = {}, q = [[sx, sy]], head = 0, seen = {};
  seen[sx + ',' + sy] = 1;
  while (head < q.length) {
    var cur = q[head++];
    var cx = cur[0], cy = cur[1];
    var dirs = [[0, -1], [0, 1], [-1, 0], [1, 0]];
    for (var i = 0; i < 4; i++) {
      var nx = cx + dirs[i][0], ny = cy + dirs[i][1];
      if (nx < 0 || ny < 0 || nx >= map.w || ny >= map.h) continue;
      var k = nx + ',' + ny;
      if (seen[k]) continue;
      if (isSolid(sceneId, nx, ny)) continue;
      seen[k] = 1; prev[k] = [cx, cy];
      if (nx === tx && ny === ty) {
        var path = [], ck = k;
        while (ck) { var p = ck.split(','); path.unshift([parseInt(p[0], 10), parseInt(p[1], 10)]); ck = prev[ck] ? prev[ck][0] + ',' + prev[ck][1] : null; }
        path.shift();
        return path;
      }
      q.push([nx, ny]);
    }
  }
  return null;
}

/* --- 出口 --- */
/* 门配置是室内门洞、外观、出口与落点的唯一来源；保留 exits 供移动引擎使用。 */
function doorTiles(door) {
  var tiles = [];
  for (var i = 0; i < door.width; i++) tiles.push([
    door.x + ((door.side === 'north' || door.side === 'south') ? i : 0),
    door.y + ((door.side === 'east' || door.side === 'west') ? i : 0)
  ]);
  return tiles;
}
function doorInward(side) {
  return side === 'north' ? [0, 1] : side === 'south' ? [0, -1] : side === 'west' ? [1, 0] : [-1, 0];
}
function doorFurnitureAt(sceneId, x, y) {
  var map = MAPS[sceneId], list = (map.roomDef && map.roomDef.props) ||
    (sceneId === 'house' ? HOUSE_FURNITURE : INTERIOR_FURNITURE[sceneId]) ||
    (typeof MILL_LIFE_FURNITURE !== 'undefined' && MILL_LIFE_FURNITURE[sceneId]) || [];
  return list.some(function (f) {
    if (f.flat) return false;
    if (f.tiles) return f.tiles.some(function (t) { return t[0] === x && t[1] === y; });
    return x >= f.x && x < f.x + f.w && y >= f.y && y < f.y + f.h;
  });
}
function installIndoorDoors(sceneId, definitions) {
  var map = MAPS[sceneId];
  if (!map || !map.indoor) throw new Error('门必须属于室内：' + sceneId);
  if (!Array.isArray(definitions) || !definitions.length) throw new Error('室内必须保留至少一扇门：' + sceneId);
  var occupied = {}, ids = {};
  var doors = definitions.map(function (def) {
    var d = Object.assign({ width: 1, style: 'wood' }, def), inward = doorInward(d.side);
    if (!d.id || ids[d.id] || ['north', 'south', 'east', 'west'].indexOf(d.side) < 0 ||
        !Number.isInteger(d.width) || d.width < 1) throw new Error('无效门配置：' + sceneId);
    ids[d.id] = true;
    if (!MAPS[d.to] || !Number.isInteger(d.tx) || !Number.isInteger(d.ty) ||
        d.tx < 0 || d.ty < 0 || d.tx >= MAPS[d.to].w || d.ty >= MAPS[d.to].h ||
        MAPS[d.to].solid[d.tx][d.ty] || doorFurnitureAt(d.to, d.tx, d.ty) ||
        (MAPS[d.to].exits || []).some(function (e) { return e.x === d.tx && e.y === d.ty; }))
      throw new Error('门外落点不可用：' + sceneId + '/' + d.id);
    var tiles = doorTiles(d);
    d.stand = tiles.map(function (t) { return [t[0] + inward[0], t[1] + inward[1]]; });
    tiles.forEach(function (t, i) {
      var x = t[0], y = t[1], s = d.stand[i];
      var onWall = d.side === 'north' ? y === 0 : d.side === 'south' ? y === map.h - 1 :
        d.side === 'west' ? x === 0 : x === map.w - 1;
      if (!Number.isInteger(x) || !Number.isInteger(y) || !onWall ||
          x < 0 || y < 0 || x >= map.w || y >= map.h ||
          ((x === 0 || x === map.w - 1) && (y === 0 || y === map.h - 1)) || occupied[x + ',' + y] ||
          doorFurnitureAt(sceneId, x, y) || doorFurnitureAt(sceneId, s[0], s[1]) || map.solid[s[0]][s[1]])
        throw new Error('门洞或门前通道被占用：' + sceneId + '/' + d.id);
      occupied[x + ',' + y] = true;
    });
    d.enter = d.enter || { x: d.stand[0][0], y: d.stand[0][1] };
    if (!d.stand.some(function (s) { return s[0] === d.enter.x && s[1] === d.enter.y; }))
      throw new Error('进门落点必须在门内侧：' + sceneId + '/' + d.id);
    d.label = d.label || '返回' + MAPS[d.to].name;
    return d;
  });
  // 全部验证后才更新，配置失败不会留下半扇门或擦掉家具碰撞。
  (map.exits || []).forEach(function (e) {
    if (e.x === 0 || e.y === 0 || e.x === map.w - 1 || e.y === map.h - 1) {
      map.solid[e.x][e.y] = 1;
      map.t[e.x][e.y] = map.roomDef ? T_BUILDING : T_WALL;
    }
  });
  map.doors = doors;
  map.exits = [];
  INTERACTABLES[sceneId] = (INTERACTABLES[sceneId] || []).filter(function (it) { return it.kind !== 'indoorExit'; });
  doors.forEach(function (d) {
    doorTiles(d).forEach(function (t) {
      map.solid[t[0]][t[1]] = 0;
      map.t[t[0]][t[1]] = map.roomDef ? T_PATH : T_FLOOR;
      map.exits.push({ x: t[0], y: t[1], to: d.to, tx: d.tx, ty: d.ty, doorId: d.id, side: d.side });
    });
    INTERACTABLES[sceneId].push({ id: 'exit_' + d.id, kind: 'indoorExit', x: d.x, y: d.y,
      stand: d.stand, label: d.label, doorId: d.id });
  });
  map.enter = doors.length ? doors[0].enter : null;
  delete map._roomCanvas;
  if (typeof groundChunks !== 'undefined') { delete groundChunks[sceneId]; delete groundChunkOrder[sceneId]; }
}
function enterIndoorDoor(it) {
  var room = MAPS[it.to];
  var door = room && (room.doors || []).filter(function (d) { return d.id === (it.doorId || 'main'); })[0];
  if (!door) { toast('这扇门尚未连接。'); return; }
  if (it.stand && !it.stand.concat([[it.x, it.y]]).some(function (p) {
    return p[0] === state.player.x && p[1] === state.player.y;
  })) { toast('请走到门旁再进入。'); return; }
  doSwitchScene(it.to, door.enter.x, door.enter.y);
}
function useIndoorExit(it) {
  var map = MAPS[state.sceneId];
  var d = (map.doors || []).filter(function (door) { return door.id === it.doorId; })[0];
  if (!d || !doorTiles(d).concat(d.stand).some(function (p) {
    return p[0] === state.player.x && p[1] === state.player.y;
  })) { toast('请走到门旁再出门。'); return; }
  doSwitchScene(d.to, d.tx, d.ty);
}
function drawIndoorDoors(g, map) {
  (map.doors || []).forEach(function (d) {
    var x = d.x * TILE, y = d.y * TILE, w = d.width * TILE;
    var frame = d.style === 'stone' ? '#B2AAA0' : d.style === 'iron' ? '#89958D' : '#98734C';
    g.save();
    if (d.side === 'north') g.translate(x, y);
    else if (d.side === 'south') g.transform(1, 0, 0, -1, x, y + TILE);
    else if (d.side === 'west') g.transform(0, 1, 1, 0, x, y);
    else g.transform(0, 1, -1, 0, x + TILE, y);
    // 暗门洞盖住墙线，框与门槛围住真正可走的格子；地垫朝向室内。
    px(g, 0, 0, w, TILE, '#302820');
    px(g, 1, 1, w - 2, TILE - 2, '#544537');
    px(g, 0, 0, 2, TILE, frame); px(g, w - 2, 0, 2, TILE, frame);
    px(g, 0, 0, w, 2, frame); px(g, 2, TILE - 3, w - 4, 3, '#C2AE7A');
    px(g, 2, TILE + 1, w - 4, 7, '#6B7960'); px(g, 4, TILE + 3, w - 8, 1, '#ADAA78');
    var cx = Math.floor(w / 2);
    px(g, cx - 1, 5, 2, 6, '#EFD18B'); px(g, cx - 3, 7, 6, 2, '#EFD18B');
    px(g, cx - 2, 6, 4, 1, '#EFD18B');
    g.restore();
  });
}
var sceneSwitch = { busy: false };
function checkExit() {
  var map = MAPS[state.sceneId];
  var px = state.player.x, py = state.player.y;
  var e;
  for (e = 0; e < (map.exits || []).length; e++) {
    var ex = map.exits[e];
    if (ex.x === px && ex.y === py) { if(ex.to==='city'&&!exploreState().city){toast('先在小镇南口驿路牌按 E 办理城市通行证。');return false;} if(ex.to === 'forest' && !exploreState().forest){toast('森林入口尚未清理。到小镇北口路牌按 E 修复。');return false;} doSwitchScene(ex.to, ex.tx, ex.ty); return true; }
  }
  if (map.eastExits) {
    for (e = 0; e < map.eastExits.length; e++) {
      var ex2 = map.eastExits[e];
      if (ex2.x === px && ex2.y === py) {
        if (!state.bridgeRepaired) { toast('小桥还没修好，东边过不去。'); return true; }
        doSwitchScene(ex2.to, ex2.tx, ex2.ty); return true;
      }
    }
  }
  return false;
}

function doSwitchScene(to, tx, ty, face) {
  if (sceneSwitch.busy) return;
  sceneSwitch.busy = true;
  var fade = $('#fade');
  fade.classList.add('on');
  setTimeout(function () {
    state.sceneId = to;
    if (to === 'house') tutorialEvent('entered');
    state.player.x = clamp(tx, 0, MAPS[to].w - 1);
    state.player.y = clamp(ty, 0, MAPS[to].h - 1);
    /* 换层落点的朝向：楼梯落点要求「面朝走出来的那侧」，
       门类连接保留原朝向不变。 */
    if (face) state.player.face = face;
    syncPlayerPixel();
    updateNpcPositions(true);
    onSceneChanged();
    registerArrival(to);      // 第七版 §33.2：首次抵达自动登记公共站
    saveNow();
    setTimeout(function () { fade.classList.remove('on'); sceneSwitch.busy = false; }, 30);
  }, 200);
}

function onSceneChanged() {
  /* 主线入口的站位随通行情况重算：桥修好、树被砍、家具挪动后都要跟上。 */
  registerStoryEntries();
  if (personalCombat.active && state.sceneId !== personalCombat.scene) personalResetCombat();
  personalCombat.mode=false;
  cam.init = false; // 换场景立即按新地图重新取景，避免室内第一帧沿用室外镜头。
  MINE_RECORD_POS='';
  if (isSolid(state.sceneId, state.player.x, state.player.y)) {
    // 落点被占用时向周围找空位
    var found = false;
    for (var r = 1; r <= (state.sceneId === 'city' ? 32 : 3) && !found; r++) {
      for (var dy = -r; dy <= r && !found; dy++) for (var dx = -r; dx <= r && !found; dx++) {
        if (!isSolid(state.sceneId, state.player.x + dx, state.player.y + dy)) {
          state.player.x += dx; state.player.y += dy; found = true;
        }
      }
    }
    if (!found) { state.player.x = state.sceneId === 'city' ? 320 : 9; state.player.y = state.sceneId === 'city' ? 470 : 10; }
  }
  /* 宫城楼层大、房间多，只在半径 3 内找空位容易把玩家塞进隔壁房间；
     这里改用全图最近可走格，楼梯落点被家具改动波及也能自救。 */
  if (isPalaceScene(state.sceneId) && isSolid(state.sceneId, state.player.x, state.player.y)) {
    var ps = nearestWalkable(state.sceneId, state.player.x, state.player.y);
    state.player.x = ps.x; state.player.y = ps.y;
  }
  syncPlayerPixel();
  Game.hoverTile = null;      // 换场景后旧的悬停格已经没有意义
  Game.selectTile = null;
  refreshHud();
  refreshHotbar();
  refreshFloorTag();
}

/* 宫城楼层牌：只在宫城场景出现，点开是楼层导览。
   户外宫苑与两处露台显示所在区域而不是楼层号。 */
function refreshFloorTag() {
  var n = document.getElementById('floorTag');
  if (!n) return;
  var sid = state && state.sceneId, fl = palaceFloorOf(sid);
  if(INDUSTRY_LABELS[sid]){n.hidden=false;n.textContent=INDUSTRY_LABELS[sid];return;}
  if (SOUTH_GATE_LABELS[sid]) { n.hidden=false;n.textContent=SOUTH_GATE_LABELS[sid];refreshInnRoomLabels();return; }
  if (UNIVERSITY_LABELS[sid]) { n.hidden=false;n.textContent=UNIVERSITY_LABELS[sid];return; }
  var serviceIndex = PALACE_SERVICE_LEVELS.indexOf(sid);
  if (!fl && serviceIndex < 0 && !(sid && PALACE_OUTDOOR.indexOf(sid) >= 0)) { n.hidden = true; return; }
  n.hidden = false;
  n.textContent = fl ? ('楼层 ' + fl.order + '／3 · ' + fl.label.replace(/^[一二三]层 · /, '')) : serviceIndex >= 0 ? PALACE_SERVICE_LABELS[serviceIndex] : '宫城 · 地面层';
}

function syncPlayerPixel() {
  var map = MAPS[state.sceneId];
  var tx = clamp(state.player.x, 0, map.w - 1);
  var ty = clamp(state.player.y, 0, map.h - 1);
  state.player.x = tx; state.player.y = ty;
  Game.ppos.x = tx * TILE + 8;
  Game.ppos.y = ty * TILE + 12;
}

