  var box = el('div', 'today-plan in-window');
  items.forEach(function (it) {
    var b = el('button', 'today-item ' + it.tier);
    b.type = 'button';
    b.appendChild(el('span', 'tier', it.tag));
    b.appendChild(el('span', 'txt', it.text));
    b.onclick = function () { it.open(); };
    box.appendChild(b);
  });
