  box.appendChild(el('p','muted','基础风险 '+engRisk(q)+' 级，来自已保存的水位、坡脚、淤积与方案。未通过复查时新工程效果不启用；原工序和机构余额保留，不重复收取班工。'));
  function button(label,opts,apply){extendedWorkButton(box,'riverbay_pit',label,opts,apply);}
