      sur.appendChild(el('p', null, '基础风险 ' + engRisk(pj) + ' / 5 · 三方意见 ' + [pj.opinions.mill && '磨坊', pj.opinions.meadow && '牧场', pj.opinions.port && '河港'].filter(Boolean).join('、')));
      b.appendChild(sur);
