      if (pj.mode === 'commission') mat.appendChild(el('p', null, '河湾施工队 4 人 · 已开工 ' + pj.crew.day + ' 天 · 已付工钱 ' + pj.crew.paid + ' 金' + (engFundsLeft(pj) < ENG_SCHEMES[pj.scheme].wage && pj.build < engSchemeBuild(pj).length ? ' · 已停工：机构余额不足' : '')));
