var iconCache = {};
ICON_ART.hardwood=function(g){px(g,3,3,4,11,'#69472F');px(g,8,4,5,10,'#97704A');px(g,4,3,2,2,'#D8B47E');px(g,9,4,3,2,'#D8B47E');};
