/* ============================================================
   统一行动结算接口（规划 P1：多处入口必须共用同一套计算）
   ------------------------------------------------------------
   所有「点一下会消耗东西的行动」都走这里，分四步且顺序固定：
     1. 校验：站位、前置条件、时间、体力、金币、材料、产物是否放得下
     2. 算成本：在「扣完材料的背包」上判断产物能不能装下，避免料被扣光
        却没拿到东西
     3. 执行：扣料 → 扣钱 → 扣体力 → 推时间 → 给产物 → 跑 apply()
     4. 保存：标脏 → 存档 → 刷新界面
   预览（costPreview）与实际执行调用的是同一个 costOf()，
   所以「界面上写的花费」和「实际扣的花费」不可能不一致。 */
function actionCostOf(opts) {
  opts = opts || {};
  var need = opts.need || {};
  var after = Object.assign({}, state.inventory);
  var i, k;
  for (k in need) {
    if (!Object.prototype.hasOwnProperty.call(need, k)) continue;
    if ((after[k] || 0) < need[k]) return { ok: false, reason: '材料不足：' + itemName(k) + ' ×' + need[k] + '（现有 ' + ((after[k] || 0)) + '）。', shortItem: k };
    after[k] -= need[k];
  }
  return {
    ok: true, after: after, need: need,
    minutes: opts.minutes || 0, energy: opts.energy || 0, coins: opts.coins || 0,
    out: opts.out || null, qty: opts.qty || 1
  };
}
function actionValidate(opts, cost) {
  if (state.coins < cost.coins) return '金币不足，尚未扣费。';
  if (!hasEnergy(cost.energy)) return false;
  if (cost.out && !canAccept(cost.after, cost.out, cost.qty)) return '背包满了，产物放不下；尚未扣除材料。';
  return true;
}
/* 只算不扣：给界面做预览用。与执行走同一份 costOf()。 */
function costPreview(opts) {
  var c = actionCostOf(opts);
  if (!c.ok) return { ok: false, reason: c.reason };
  var parts = [];
  if (c.minutes) parts.push(c.minutes + ' 分钟');
  if (c.energy) parts.push(c.energy + ' 体力');
  if (c.coins) parts.push(c.coins + ' 金');
  for (var k in c.need) if (Object.prototype.hasOwnProperty.call(c.need, k)) parts.push(itemName(k) + ' ×' + c.need[k]);
  return { ok: true, text: parts.join(' · ') || '无消耗', minutes: c.minutes, coins: c.coins, energy: c.energy };
}
/* 统一执行入口。site 检查与 guard 属于「在哪里／凭什么」，也收在这里。 */
function performAction(opts) {
  opts = opts || {};
  if (opts.point && (state.sceneId !== opts.point.scene ||
      Math.abs(state.player.x - opts.point.x) + Math.abs(state.player.y - opts.point.y) > (opts.point.leash || 1))) {
    toast('请到' + (opts.point.label || '设施') + '旁操作。'); return false;
  }
  if (opts.guard && !opts.guard()) { toast(opts.reason || '当前条件尚未满足。'); return false; }
  var cost = actionCostOf(opts);
  if (!cost.ok) { toast(cost.reason); return false; }
  if (!canSpendGameMinutes(cost.minutes)) return false;
  var v = actionValidate(opts, cost);
  if (v !== true) { if (v) toast(v); return false; }
  for (var k in cost.need) if (Object.prototype.hasOwnProperty.call(cost.need, k)) invRemove(k, cost.need[k]);
  state.coins -= cost.coins;
  state.energy -= cost.energy;
  spendGameMinutes(cost.minutes);
  if (cost.out) invAdd(cost.out, cost.qty);
  if (opts.apply) opts.apply();
  markDirty(); saveNow(); refreshHud(); refreshWindow();
  if (opts.silent !== true) Audio2.play('place');
  return true;
}
/* 既有入口一律转调 performAction，逐步收回重复实现 */
function ruralWorkAction(point, opts, apply) {
  var o = {};
  for (var k in opts) if (Object.prototype.hasOwnProperty.call(opts, k)) o[k] = opts[k];
  o.point = point; o.apply = apply; o.silent = true;
  return performAction(o);
}
function cityWork(opts) {
  var need = {};
  (opts.need || []).forEach(function (p) { need[p[0]] = (need[p[0]] || 0) + p[1]; });
  var ok = performAction({
    need: need, out: opts.out, qty: opts.qty || 1,
    energy: opts.energy || 0, minutes: opts.minutes || 30,
    guard: opts.guard, reason: opts.reason
  });
  if (ok) {
    /* R5-0：票据出厂就登记取得日与来源，日后兑付、典当才查得到出处 */
    if (BILL_QUOTES[opts.out]) {
      var e2 = exploreState(), n2 = opts.qty || 1;
      if (!Array.isArray(e2.billLots)) e2.billLots = [];
      e2.billLots.push({ item: opts.out, qty: n2, day: state.totalDay });
      billTxLog(opts.out, 'issue', 0, BILL_QUOTES[opts.out].source);
    }
    toast((opts.done || '完成了') + '，获得 ' + itemName(opts.out) + ' ×' + (opts.qty || 1) + '。');
  }
  return ok;
}
