  m.trainingDays=Array.isArray(r.trainingDays)?r.trainingDays.filter(function(d){return Number.isInteger(d)&&d>0&&d<=100000;}).filter(function(d,i,a){return a.indexOf(d)===i;}).sort(function(a,b){return a-b;}).slice(-12):[];
