var baseMs1GateAllowed = extendedGateAllowed;
extendedGateAllowed = function (key) {
  if (key === 'ms1_pine') return baseMs1GateAllowed('neighbor');
  if (key === 'ms1_tide') return baseMs1GateAllowed('port');
  if (key === 'ms1_capital') return baseMs1GateAllowed('port');
  if (key === 'ms1_echo') return extendedGateAllowed('ms1_pine');
  return baseMs1GateAllowed(key);
};
var baseMs1GateReason = extendedGateReason;
extendedGateReason = function (key) {
  if (key === 'ms1_pine') return '未解锁 · 取得邻领通行文书（完成边境任务并核对旧界碑）';
  if (key === 'ms1_tide') return '未解锁 · 完成河港调查并安排好航路';
  if (key === 'ms1_capital') return '未解锁 · 沿皇家驿路抵达王都';
  if (key === 'ms1_echo') return '未解锁 · 取得现场核验许可，并有向导带路上山径';
  return baseMs1GateReason(key);
};

