/* --- 地点里的可交互点：先给位置，幕里的现场操作在 M1—M3 接上 --- */
/* --- 地点里的可交互点：先给位置，幕里的现场操作在 M1—M3 接上 ---
   站位要按实际通行算：操作台常常紧挨着柜子或桌子，
   固定四邻里有一格是实心的，站到那格就按不到 E。 */
function ms1Site(scene, x, y, label, site) {
  var stand = [[x, y + 1], [x - 1, y], [x + 1, y], [x, y - 1]].filter(function (c) {
    return !isSolid(scene, c[0], c[1]);
  });
  if (!stand.length) stand.push([x, y + 1]);
  INTERACTABLES[scene].push({ kind: 'extendedLife', work: site, x: x, y: y, label: label, stand: stand });
}
ms1Site('ms1_pine_village', 17, 12, '村口的旧路牌与驿车停运记录', 'ms1_pine_sign');
