drawMillLifeFurniture=function(g,f){if(!f||!f.extended)return baseDrawMillLifeFurniture(g,f);drawExtendedFurniture(g,f);};

/* 「工程已验收并交付」的单一判定读法：只看项目记录的最终阶段，
   不再用 certified 这种中途就会为真的字段去代表交付完成。 */
function projectAcceptedFlag(p){return !!(p&&p.projects&&p.projects[ENG_PROJECT_ID]&&p.projects[ENG_PROJECT_ID].phase==='accepted');}
function extendedSceneAllowed(s,region){
  if(!s||!s.professionalLife||!s.wetlandLife||!s.militaryLife)return false;
  var p=s.professionalLife,w=s.wetlandLife,m=s.militaryLife,r=p.routes||{},passes=p.passes||{};
  if(region==='wetland')return !!s.bridgeRepaired;
  if(region==='vineyard')return !!(s.millLife&&s.millLife.inspected)||r.engineering>=1||r.trade>=1;
  if(region==='clinic')return !!w.causeFound&&(p.vineyard.harvested>0||p.access.clinic)||r.patrol>=1;
  if(region==='port')return !!w.causeFound||r.trade>=2;
  if(region==='quarry')return !!(s.exploration&&s.exploration.mine)||r.engineering>=1;
  /* R3：与 extendedGateAllowed 同一套口径 —— 矿山排水或磨坊维修任一实践验收
     通过即可进场。两处必须同步改，否则门口写一种说法、进不去却是另一种。 */
  if(region==='waterworks'){
    var minePractice=!!(s.exploration&&s.exploration.mineWorks&&s.exploration.mineWorks.inspected);
    var millPractice=!!(s.millLife&&s.millLife.inspected);
    return minePractice||millPractice||!!(p.quarry.surveyed&&p.port.manifestChecked)||r.engineering>=2||r.trade>=4;
  }
  if(region==='cloud_pass')return projectAcceptedFlag(p)&&p.trust>0||!!passes.visit;
  if(region==='border_camp')return projectAcceptedFlag(p)||!!passes.commission||(m.registered&&MIL_COMMAND_RANKS.indexOf(m.rank)>=0);
  if(region==='old_road')return !!m.campaign.active||!!m.campaign.reported||!!passes.commission;
  if(region==='neighbor')return !!m.campaign.reported&&!!m.neighbor.oldroadVerified||!!passes.visit;
  return true;
}
