function personalMaxHp(body){return 60+Math.max(0,(body===undefined?charAttr('body'):body)-5)*4;}
function normalizePersonal(raw,body,today){
  raw=raw&&typeof raw==='object'?raw:{};
  function num(v,d,lo,hi){return Number.isFinite(v)?clamp(Math.floor(v),lo,hi):d;}
  var p={dodgeKey:raw.dodgeKey==='x'?'x':'Shift',tracked:raw.tracked===true,trained:raw.trained===true,training:{sword:{hit:false,dodge:false},blade:{hit:false,dodge:false}},weapons:{},equipped:null,
    hp:num(raw.hp,personalMaxHp(body),1,personalMaxHp(body)),resolved:{},examples:{},luckCycles:{},meetingDay:num(raw.meetingDay,-7,-7,today),
    study:raw.study===true,analysis:raw.analysis===true,dutyDay:num(raw.dutyDay,0,0,today),dutyDone:raw.dutyDone===true,steelStory:raw.steelStory===true};
  ['sword','blade'].forEach(function(k){
    var t=(raw.training||{})[k]||{};p.training[k]={hit:t.hit===true,dodge:t.dodge===true};
    var w=(raw.weapons||{})[k];if(p.trained&&w&&typeof w==='object')p.weapons[k]={tier:num(w.tier,0,0,3),name:typeof w.name==='string'?w.name.slice(0,24):'初次训练',memento:typeof w.memento==='string'?w.memento.slice(0,40):'小镇训练绳结'};
  });
  if(p.trained&&!Object.keys(p.weapons).length)p.weapons.sword={tier:0,name:'初次训练',memento:'小镇训练绳结'};
  p.equipped=p.weapons[raw.equipped]?raw.equipped:(Object.keys(p.weapons)[0]||null);
  ['hollow','canal'].forEach(function(k){var r=(raw.resolved||{})[k];if(r&&['fight','bypass'].indexOf(r.method)>=0)p.resolved[k]={method:r.method,day:num(r.day,1,1,today)};});
  CHAR_TALENT_IDS.forEach(function(k){if(typeof (raw.examples||{})[k]==='string')p.examples[k]=raw.examples[k].slice(0,180);});
  Object.keys(raw.luckCycles||{}).slice(0,500).forEach(function(k){if(/^((forest|mine[123]):\d+,\d+)$/.test(k))p.luckCycles[k]=num(raw.luckCycles[k],0,0,today);});
  return p;
}
function personalState(){if(!state.personal)state.personal=normalizePersonal(null,charAttr('body'),state.totalDay);return state.personal;}
