// 矿样研究与入门维修提供实际智力路线；公共责任必须跨日复核。
function personalResearchMinutes(){return Math.ceil(30*(1-Math.min(.25,Math.max(0,charAttr('int')-5)*.01+(hasTalent('focus_read')?.10:0))));}
function personalStudy(){var p=personalState(),mins=personalResearchMinutes();return performAction({point:{scene:'mine1',x:14,y:20,label:'矿样台'},minutes:mins,energy:2,guard:function(){return personalSafeAction()&&!p.study;},apply:function(){p.study=true;grantCharExpOnce('personal.mine-study',20,'发现');if(hasTalent('focus_read'))personalExample('focus_read','矿样研究：30 → '+mins+'分钟。');toast('研究完成：北侧 (4,3) 的铜矿有富集亮斑，矿样记录已保存。');}});}
function personalAnalyze(){var p=personalState(),effective=Math.min(20,charAttr('int')+(hasTalent('craft_grasp')?2:0));return performAction({point:personalTownPoint(),minutes:15,energy:1,guard:function(){return personalSafeAction()&&!p.analysis&&effective>=10&&rookieState().engineering===1;},reason:'先在任务板报名水泵维修；有效智力需10。保底路线仍可逐步借工具维修。',apply:function(){p.analysis=true;rookieState().engineering=3;if(hasTalent('craft_grasp'))personalExample('craft_grasp','水泵分析：智力 '+charAttr('int')+' +2 = '+effective+'，核对出松栓而非断水；省去往返询问。');toast('分析松栓与昨日用水记录，工程入门已推进到紧固试水。');}});}
function personalDuty(){var p=personalState();if(!hasTalent('stand_forward')&&!p.dutyDay)return false;
 return performAction({point:personalTownPoint(),minutes:p.dutyDay?20:15,energy:3,guard:function(){return personalSafeAction()&&!p.dutyDone&&(p.dutyDay||rookieState().engineering>=4)&&(!p.dutyDay||state.totalDay>p.dutyDay);},reason:'先完成入门水泵紧固试水，再接下值守；值守须在次日复核，不能同天结案。',apply:function(){
 if(!p.dutyDay){p.dutyDay=state.totalDay;personalExample('stand_forward','承担水泵安全值守：3体力并预约次日复核；待完成责任。');toast('你接下值守，隔天到工坊复核压力；洗点不撤销责任。');}
 else{p.dutyDone=true;state.coins+=25;bumpRoute('engineering',1);grantCharExpOnce('personal.pump-duty',60,'公共责任');personalExample('stand_forward','已跨日复核水泵，得到25金与工程责任记录。');toast('压力稳定、警示解除。值守完成。');}}});}
function renderPersonalPump(b){var p=personalState();charNote(b,'水泵额外分析：有效智力 '+Math.min(20,charAttr('int')+(hasTalent('craft_grasp')?2:0))+' / 10；工艺理解 +2，检定最终最多20。');b.appendChild(mkBtn('分析水泵松栓 · 15分钟 / 1体力','sm',personalAnalyze));if(hasTalent('stand_forward')||p.dutyDay){b.appendChild(mkBtn(p.dutyDone?'水泵值守已完成':p.dutyDay?'次日复核值守 · 20分钟 / 3体力':'挺身而出：承担水泵值守 · 15分钟 / 3体力','sm',personalDuty));}}
function personalMeeting(){var p=personalState();return performAction({point:{scene:'town',x:12,y:13,label:'集市'},out:'berry',qty:1,minutes:5,guard:function(){return personalSafeAction()&&hasTalent('good_meeting')&&state.totalDay-p.meetingDay>=7;},reason:'好时相逢每七个世界日一次；需要先学习天赋。',apply:function(){p.meetingDay=state.totalDay;personalExample('good_meeting','集市居民赠送普通野莓1份，下次可遇第'+(p.meetingDay+7)+'天。');toast('集市居民与你分享一份野莓和今日农事见闻。');}});}
function personalLuckyRate(){return Math.min(.17,Math.max(0,charAttr('luck')-5)*.01+(hasTalent('lucky_find')?.03:0));}
function personalLuckyRoll(key,day){var h=2166136261;var s=key+':'+day;for(var i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);// 混合高低位，避免相邻世界日的字符串哈希长期聚在同一概率区间。
 h=Math.imul(h^(h>>>16),0x7feb352d);h=Math.imul(h^(h>>>15),0x846ca68b);h^=h>>>16;return (h>>>0)/4294967296;}
var personalGatherBase=gatherExplore;
gatherExplore=function(tool,x,y){
 var sc=state.sceneId,n=exploreNode(sc,x,y),before=n&&n.saved.hp,cycle=n&&n.saved.day;
 // 一个节点同日最多完成一个再生周期；用完成日固化奖励，不在重载时重抽。
 cycle=state.totalDay;
 var ok=personalGatherBase(tool,x,y);if(!ok||!n||before<=0||n.saved.hp!==0||['wood','stone','copper_ore','iron_ore','mushroom'].indexOf(n.def.item)<0)return ok;
 var p=personalState(),key=sc+':'+key2(x,y);if(p.luckCycles[key]===cycle)return ok;
 p.luckCycles[key]=cycle;var rate=personalLuckyRate(),roll=personalLuckyRoll(key,cycle);
 if(roll<rate&&bagAccepts(n.def.item,1)){invAdd(n.def.item,1);toast('顺手找到普通'+itemName(n.def.item)+' ×1。');}
 if(hasTalent('lucky_find'))personalExample('lucky_find',MAPS[sc].name+' ('+x+','+y+')：概率 '+Math.round(rate*100)+'%，'+(roll<rate?'额外产物检定成功':'本周期未额外获得')+'；每节点每周期仅检定一次。');
 markDirty();refreshHud();return ok;
};
