function personalResetCombat(){document.documentElement.classList.remove('personal-encounter');personalCombat={active:false,mode:false,scene:'',cool:0,dodge:0,inv:0,stun:0,flash:0,enemy:null,trial:null,event:null};clearKeys();}
function personalSetScene(sc,x,y){state.sceneId=sc;state.player.x=x;state.player.y=y;syncPlayerPixel();onSceneChanged();}
function personalStart(event,trial){
 if(!personalSafeAction())return false;
 var p=personalState(),training=event==='training';if(training){if(!personalNear('town',17,13)||['sword','blade'].indexOf(trial)<0){toast('请到小镇训练牌旁。');return false;}}
 else if(['hollow','canal'].indexOf(event)<0||!personalNear('mine1',14,20)||!p.trained||!p.equipped||p.resolved[event]){toast('需在矿山一层支路入口旁，完成训练并装备旧刃；已解决的事件不重复领奖。');return false;}
 closeWindow();personalResetCombat();var scene=training?'r2_training':'r2_hollow',entry=MAPS[scene].enter;personalSetScene(scene,entry.x,entry.y);state.player.face='up';
 document.documentElement.classList.add('personal-encounter');personalCombat.active=true;personalCombat.mode=true;personalCombat.scene=state.sceneId;personalCombat.event=event;personalCombat.trial=training?trial:null;
 personalCombat.enemy={x:7*TILE+8,y:6*TILE+12,hp:training?999:48,maxHp:48,phase:'approach',timer:0,tx:0,ty:0,kind:event==='canal'?'rush':'slow'};
 toast(training?'训练：走近、朝向假人按空格；观察举爪预警并闪避，练习受击不扣生命，然后撤回领取。':'危险：生物会先举爪或伏身预警；移动或闪避避开标记。可随时撤回。');return true;
}
function personalResolve(event,method){
 var p=personalState();if(p.resolved[event])return false;p.resolved[event]={method:method,day:state.totalDay};state.coins+=35;
 var key='personal.encounter.'+event,c=charState();if(!Object.prototype.hasOwnProperty.call(c.expGrants||{},key)){if(!c.expGrants)c.expGrants={};c.expGrants[key]=state.totalDay;grantCharExpDaily('danger',10);}
 toast('支路安全记录完成（'+(method==='fight'?'驱离':'绕行标记')+'），获得35金与10经验；两种解法同奖。');markDirty();return true;
}
function personalBypass(event){var p=personalState();return performAction({point:{scene:'mine1',x:14,y:20,label:'支路警示牌'},minutes:20,energy:3,guard:function(){return personalSafeAction()&&['hollow','canal'].indexOf(event)>=0&&!p.resolved[event];},apply:function(){personalResolve(event,'bypass');}});}
function personalLeave(failed){
 var sc=state&&state.sceneId,c=personalCombat;if(!state||(sc!=='r2_training'&&sc!=='r2_hollow')){if(c.active)personalResetCombat();return;}
 var training=sc==='r2_training';personalResetCombat();closeWindow();personalSetScene(training?'town':'mine1',training?17:14,training?14:21);
 if(failed){personalState().hp=Math.ceil(personalMaxHp()*.5);state.timeMinutes=Math.min(CFG.dayEnd,state.timeMinutes+60);toast('已救回安全入口：恢复半血，推进60分钟，物品与金币全部保留。');}
 markDirty();saveNow();refreshHud();if(failed&&state.timeMinutes>=CFG.dayEnd)autoSleep();
}
function personalToggle(){if(timePaused()||!personalWeapon())return false;personalCombat.mode=!personalCombat.mode;toast(personalCombat.mode?'武器模式：空格攻击 / Shift闪避':'工具模式：空格使用农具');return true;}
function personalAttack(){
 var c=personalCombat,w=personalWeapon();if(timePaused()||!c.mode||!w||c.cool>0||c.stun>0)return false;
 c.cool=w.interval;c.flash=.18;var e=c.enemy;if(!c.active||!e)return true;
 var f=FACE_DIR[state.player.face]||[0,1],dx=e.x-Game.ppos.x,dy=e.y-Game.ppos.y,forward=dx*f[0]+dy*f[1],side=Math.abs(dx*f[1]-dy*f[0]);
 if(forward<0||forward>w.range||side>w.width)return true;
 if(c.trial){personalState().training[c.trial].hit=true;toast('训练命中！再练闪避，然后撤回。');markDirty();}
 else{var dmg=Math.max(1,Math.round(w.damage*(w.kind==='blade'?.85:1)-1));e.hp-=dmg;toast('命中 '+dmg+' · 敌方生命 '+Math.max(0,e.hp)+'/48');if(e.hp<=0){var event=c.event;personalResolve(event,'fight');personalLeave(false);}}
 Audio2.play('breakrock');return true;
}
function personalDodge(){var c=personalCombat;if(timePaused()||!c.mode||!personalWeapon()||c.dodge>0||c.stun>0)return false;
 var f=FACE_DIR[state.player.face]||[0,1];for(var i=0;i<12;i++){var nx=Game.ppos.x+f[0]*TILE*.1,ny=Game.ppos.y+f[1]*TILE*.1;if(isSolid(state.sceneId,Math.floor(nx/TILE),Math.floor(ny/TILE)))break;Game.ppos.x=nx;Game.ppos.y=ny;}
 state.player.x=Math.floor(Game.ppos.x/TILE);state.player.y=Math.floor(Game.ppos.y/TILE);c.dodge=1.6;c.inv=.16;
 if(c.trial){personalState().training[c.trial].dodge=true;toast('闪避完成！命中后可撤回训练牌。');markDirty();}return true;
}
function personalStunSeconds(){return .35*(1-Math.min(.25,Math.max(0,charAttr('nerve')-5)*.01+(hasTalent('steady')?.1:0)));}
function personalCanApproach(x,y){var e=personalCombat.active&&personalCombat.enemy;if(!e)return true;var d=Math.hypot(x-e.x,y-e.y);return d>=TILE*.55||d>Math.hypot(Game.ppos.x-e.x,Game.ppos.y-e.y);}
function personalTakeHit(){var c=personalCombat;if(c.inv>0)return false;if(c.trial){c.inv=.6;c.stun=personalStunSeconds();toast('练习受击：未扣生命。观察举爪预警，移动或闪避离开标记。');return true;}var p=personalState();p.hp=Math.max(0,p.hp-8);c.inv=.6;c.stun=personalStunSeconds();if(hasTalent('steady'))personalExample('steady','受击硬直 .35 → '+c.stun.toFixed(3)+'秒；暂停时不推进。');markDirty();if(p.hp===0)personalLeave(true);return true;}
function tickPersonal(dt){
 var c=personalCombat;if(!state)return;if(timePaused())return;
 ['cool','dodge','inv','stun','flash'].forEach(function(k){c[k]=Math.max(0,c[k]-dt);});
 if(c.active&&state.sceneId!==c.scene){personalResetCombat();return;}
 var e=c.enemy;if(!c.active||!e)return;
 var dist=Math.hypot(e.x-Game.ppos.x,e.y-Game.ppos.y);
 e.timer=Math.max(0,e.timer-dt);
 if(e.phase==='recover'){if(e.timer<=0)e.phase='approach';return;}
 if(e.phase==='warn'){if(e.timer<=0){e.phase='attack';e.timer=e.kind==='rush'?.3:.12;}return;}
 if(e.phase==='attack'){
  if(e.kind==='rush'){var d=Math.hypot(e.tx-e.x,e.ty-e.y);if(d>1){var step=Math.min(d,5*TILE*dt),nx=e.x+(e.tx-e.x)/d*step,ny=e.y+(e.ty-e.y)/d*step;if(!isSolid(c.scene,Math.floor(nx/TILE),Math.floor(ny/TILE))){e.x=nx;e.y=ny;}}}
  if(Math.hypot(Game.ppos.x-(e.kind==='rush'?e.x:e.tx),Game.ppos.y-(e.kind==='rush'?e.y:e.ty))<TILE*.75)personalTakeHit();
  if(e.timer<=0){e.phase='recover';e.timer=.9;}return;
 }
 if(dist<(e.kind==='rush'?4:1.35)*TILE){e.phase='warn';e.timer=e.kind==='rush'?.9:.75;e.tx=Game.ppos.x;e.ty=Game.ppos.y;return;}
 if(c.trial)return;
 var speed=1.3*TILE*dt;if(dist>0){var nx=e.x+(Game.ppos.x-e.x)/dist*speed,ny=e.y+(Game.ppos.y-e.y)/dist*speed;if(!isSolid(c.scene,Math.floor(nx/TILE),Math.floor(ny/TILE))){e.x=nx;e.y=ny;}}
}
function drawPersonal(g,ox,oy){
 var c=personalCombat,e=c.enemy;if(!c.active)return;g.save();g.translate(-ox,-oy);
 if(e){var x=e.x,y=e.y;px(g,x-7,y-11,14,10,c.trial?'#9A795B':e.kind==='rush'?'#977399':'#699A83');px(g,x-5,y-14,3,5,'#D6D4B7');px(g,x+2,y-14,3,5,'#D6D4B7');px(g,x-3,y-8,1,1,'#283831');px(g,x+3,y-8,1,1,'#283831');
 if(e.phase==='warn'||e.phase==='attack'){g.strokeStyle='#F9CA69';g.lineWidth=2;g.strokeRect(e.tx-TILE*.75,e.ty-TILE*.75,TILE*1.5,TILE*1.5);g.fillStyle='#F9CA69';g.font='8px monospace';g.fillText(e.kind==='rush'?'! 冲刺':'! 举爪',x-14,y-20);}
 if(!c.trial){px(g,x-10,y-19,20,2,'#482E37');px(g,x-10,y-19,20*Math.max(0,e.hp)/48,2,'#DC8C70');}}
 if(c.mode){var f=FACE_DIR[state.player.face]||[0,1],w=personalWeapon(),px2=Game.ppos.x,py2=Game.ppos.y;if(w){g.strokeStyle=c.flash>0?'#FFF0AD':'#8DA9AA';g.lineWidth=c.flash>0?3:1;g.beginPath();g.moveTo(px2+f[0]*7,py2-5+f[1]*7);g.lineTo(px2+f[0]*w.range,py2-5+f[1]*w.range);g.stroke();}}
 g.restore();
}
