  grantWaterworksCertificate: function () {
    var p = professionalLifeState(), pj = engProject();
    pj.survey = { level: 2, day: state.totalDay, east: 'sound', silt: 'light' };
    pj.practice = 'mill';
    pj.phase = 'certify';
    deriveWaterworksFromProject(p, p.waterworks);
    return true;
  },
  engProjectInfo: function () {
    var pj = engProject();
    return {
      id: pj.id, phase: pj.phase, step: engPhaseIndex(pj), scheme: pj.scheme,
      survey: pj.survey, practice: pj.practice, emergency: pj.emergency, opinions: pj.opinions,
      stone: pj.stone, kit: pj.kit, build: pj.build, mode: pj.mode, crew: pj.crew,
      trialDay: pj.trialDay, maintDay: pj.maintDay, maintCount: pj.maintCount,
      safety: pj.safety, duty: pj.duty, outcome: engOutcome(), outcomeText: engOutcomeText(), dutyText: engDutyText(pj),
      funds: pj.funds, fundsLeft: engFundsLeft(pj), risk: engRisk(pj),
      steps: engSchemeBuild(pj).map(function (s) { return s; }),
      scope: professionalLifeState().waterworks.scope,
      allocation: professionalLifeState().waterworks.allocation,
      policy: professionalWaterPolicy(), shipping: professionalShippingMinutes(60),
      practiceRoute: engPracticeRoute()
    };
  },
  engInfo: function () {
    var e = engCareer();
    return { stage: e.stage, post: e.post, incident: e.incident, choice: e.choice,
      hearing: e.hearing, budget: e.budget, budgetGranted: !!e.budgetGranted, memories: e.memories, can: engCan(), playerCoins: state.coins };
  },
  /* 测试用：确认关键工序不能在远处完成 —— 走与真实按钮同一个 extendedWork 入口 */
  engRemoteProbe: function (site) {
    var fired = false, before = JSON.stringify(engProject());
    extendedWork(site, '探针', { minutes: 1, guard: function () { return true; } }, function () { fired = true; });
    return { fired: fired, unchanged: JSON.stringify(engProject()) === before };
  },
  /* 测试用：把工程推到「方案已定、石料已到场」的自洽状态。
     材料物流链由既有 R2 用例覆盖，这里只夹具它已完成；
     工程内部的每一步仍由验收脚本走真实界面与真实位置。 */
  engFixtureToScheme: function (scheme) {
    var p = professionalLifeState(), pj = engProject(), e = engCareer();
    pj.survey = { level: 2, day: Math.max(1, state.totalDay), east: 'sound', silt: 'light' };
    pj.practice = 'mill';
    pj.phase = 'certify';
    deriveWaterworksFromProject(p, p.waterworks);
    e.stage = 4; e.post = 'waterworks_engineer'; e.incident = 'channel'; e.choice = 'channel'; e.postEval = 'incident';
    applyEngChoice();
    pj.opinions = { mill: true, meadow: true, port: true };
    engGrantBudget();
    if (!engConfirmScheme(scheme || 'conservative')) return false;
    pj.stone = true; pj.stoneDay = state.totalDay;
    deriveWaterworksFromProject(p, p.waterworks);
    state.inventory.iron_ingot = (state.inventory.iron_ingot || 0) + 1;
    state.energy = Math.max(state.energy, 60);
    state.timeMinutes = Math.max(state.timeMinutes, 480);
    markDirty();
    return true;
  },
  /* 测试用：把工程推到「已验收交付」。只验收下游后果的脚本（CDE 等）
     用它跳过工程内部流程 —— 那些步骤由 run-r3-project 逐键验证。 */
  engFixtureAccepted: function (scheme) {
    if (!this.engFixtureToScheme(scheme || 'conservative')) return false;
    var q = engProject();
    q.kit = 1; engAdvance('materials');
    q.build = engSchemeBuild(q).length; q.mode = 'self'; engAdvance('build');
    q.trialDay = Math.max(1, state.totalDay - 1);
    engAdvance('trial');
    return engAcceptProject();
  },
  /* 夹具：世界日期前进一天。委托施工每天只能开一道工序，
     用它替代真实睡觉流程，不影响资金与工序的结算逻辑。 */
  engAdvanceDay: function () { state.totalDay++; markDirty(); if (typeof refreshWindow === 'function') refreshWindow(); return state.totalDay; },
  engStep: function (what, arg) {
    var e = engCareer();
    if (what === 'sign') { if (e.stage !== 0 || !engHasCertificate()) return false; e.stage = 1; rememberChoice('noya', '独立署名水利报告'); return true; }
    if (what === 'incident') {
      if (e.stage !== 1 || e.incident || ['field','channel'].indexOf(arg)<0) return false;
      e.incident = arg; e.choice = arg; e.stage = 2; e.postEval = 'incident';
      rememberChoice('noya', arg === 'field' ? '事故中先保农田' : '事故中先保通航');
      rememberChoice('martin', arg === 'field' ? '事故中先保农田' : '事故中先保通航');
      applyEngChoice();
      return true;
    }
    if (what === 'preventive') { return engTakePostEval('gate', arg === 'labor' ? 'labor' : 'mat'); }
    if (what === 'post') { if (e.stage < 2 || e.post) return false; e.post = 'waterworks_engineer'; e.stage = 4; rememberChoice('noya', (e.postEval === 'preventive' ? '汛前预防' : '事故处置') + '后接下工程岗位'); return true; }
    if (what === 'budget') { if (e.stage < 3 || e.budgetGranted || engProject().funds.granted > 0) return false; return engGrantBudget(); }
    if (what === 'scheme') { return engConfirmScheme(arg); }
    if (what === 'accept') { return engAcceptProject(); }
    if (what === 'dutyInspect') { return engDutyInspect(engProject()); }
    if (what === 'defer') { return engDutyDefer(engProject(), arg || '人手不足'); }
    if (what === 'handover') { return engDutyHandover(engProject()); }
    if (what === 'release') { return engDutyRelease(engProject()); }
    return false;
  },
